window.FA_EX=window.FA_EX||{};Object.assign(window.FA_EX,{
"0259":{"name":"شنا سوئدی دست جمع","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها نزدیک هم و دقیقاً زیر شانه‌ها.","میان‌تنه را منقبض کنید و با آرنج‌های نزدیک بدن، بدن را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2398":{"name":"شنا سوئدی دست جمع (زانوزده)","steps":["روی دست و زانو شروع کنید؛ دست‌ها به عرض شانه و زانوها به عرض لگن.","تنه بالایی را با خم‌کردن آرنج‌های نزدیک پهلوها به سمت زمین پایین ببرید.","وقتی سینه کمی بالای زمین بود مکث کنید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0260":{"name":"کوکون (کرانچ زانوجمع)","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را به‌آرامی از زمین بلند کنید و تا زاویه ۴۵ درجه به جلو خم شوید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1468":{"name":"چرخش خرچنگ با لمس انگشت پا","steps":["روی زمین بنشینید؛ زانوها خم و کف پاها صاف روی زمین.","دست‌ها را پشت سر با انگشتان رو به پاها بگذارید و لگن را از زمین بلند کنید.","یک پا را صاف جلوی خود دراز کنید و همزمان دست مخالف را به سمت پنجه برسانید.","به موقعیت شروع برگردید و حرکت را در طرف دیگر تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0262":{"name":"کرانچ ضربدری","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را از زمین بلند کنید و بچرخانید تا آرنج راست به سمت زانوی چپ برود.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","در طرف دیگر با آوردن آرنج چپ به سمت زانوی راست تکرار کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0267":{"name":"کرانچ با بازوهای بالای سر","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","بازوها را صاف بالای سر دراز کنید.","با انقباض شکم، تنه را از زمین بلند کنید؛ به سمت زانوها جمع شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0271":{"name":"کرانچ روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","به عقب روی توپ خم شوید تا کمر تکیه‌دار شود و تنه بالایی موازی زمین قرار گیرد.","دست‌ها را پشت سر یا روی سینه بگذارید.","شکم را منقبض کنید و تنه را به سمت زانوها بلند کنید؛ تنه به جلو جمع شود.","در بالای حرکت مکث کنید، سپس تنه بالایی را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0272":{"name":"کرانچ روی توپ سوئیسی با بازوی صاف","steps":["روی توپ سوئیسی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","به عقب روی توپ خم شوید تا کمر تکیه‌دار شود و تنه بالایی موازی زمین قرار گیرد.","دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.","شکم را منقبض کنید و تنه را از روی توپ بلند کنید؛ شانه‌ها به سمت لگن.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0274":{"name":"کرانچ روی زمین","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","شکم را منقبض کنید و شانه‌ها را از زمین بلند کنید؛ به سمت زانوها کرانچ بزنید.","در بالا مکث کنید، سپس شانه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3016":{"name":"کرانچ نیمه","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را به‌آرامی از زمین بلند کنید و تا زاویه ۴۵ درجه به جلو خم شوید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3769":{"name":"اسکوات تعظیم (کرتسی)","steps":["بایستید و پاها را به عرض شانه باز کنید.","با پای راست مورب به عقب و ضربدری از عرض بدن قدم بردارید؛ پشت پای چپ.","هر دو زانو را مثل تعظیم (کرتسی) خم کنید و بدن را به سمت زمین پایین ببرید.","تنه صاف و وزن بدن روی پای جلو باشد.","با فشار پای جلو به موقعیت شروع برگردید.","در طرف دیگر با گام مورب پای چپ به عقب و ضربدری از عرض بدن تکرار کنید."]},
"2331":{"name":"دوچرخه کراس‌ترینر","steps":["ارتفاع صندلی را تنظیم کنید و روی کراس‌ترینر جای بگیرید.","پاها را روی رکاب‌ها بگذارید و فرمان را بگیرید.","رکاب‌زنی را با حرکتی نرم و کنترل‌شده شروع کنید.","سرعت ثابت را حفظ کنید و در صورت تمایل مقاومت را افزایش دهید.","برای مدت دلخواه تمرین هوازی رکاب‌زنی را ادامه دهید."]},
"0276":{"name":"دی‌دباگ","steps":["به پشت دراز بکشید؛ بازوها به سمت سقف دراز.","زانوها را خم کنید و پاها را از زمین بلند کنید تا لگن و زانوها با زاویه ۹۰ درجه قرار گیرند.","میان‌تنه و کمر پایین را منقبض کنید تا کمر به زمین بچسبد.","دست راست و پای چپ را صاف و کمی بالای زمین به‌آرامی پایین ببرید.","لحظه‌ای مکث کنید، سپس به موقعیت شروع برگردید.","حرکت را با دست چپ و پای راست تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0277":{"name":"کرانچ زیرسینه","steps":["روی میز زیرسینه دراز بکشید؛ پاها ثابت و زانوها با زاویه ۹۰ درجه خم.","دست‌ها را پشت سر یا روی سینه بگذارید.","شکم را منقبض کنید و تنه را به سمت زانوها بلند و جمع کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0279":{"name":"شنا سوئدی زیرسینه","steps":["دست‌ها را کمی بازتر از عرض شانه روی زمین بگذارید و پاها را روی سطح ثابت بلند کنید.","بدن را در خطی صاف از سر تا پنجه نگه دارید؛ عضلات میان‌تنه منقبض.","با خم‌کردن آرنج‌ها و نزدیک‌نگه‌داشتن آن‌ها به بدن، سینه را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0282":{"name":"درازنشست زیرسینه","steps":["روی میز زیرسینه دراز بکشید؛ پاها ثابت و زانوها خم.","دست‌ها را پشت سر یا روی سینه بگذارید.","شکم را منقبض کنید و تنه را از روی میز بلند کنید؛ به سمت زانوها کرانچ بزنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1274":{"name":"شنا سوئدی عمیق با دمبل","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و بدن در خطی صاف.","با خم‌کردن آرنج‌ها و نزدیک‌نگه‌داشتن آن‌ها به بدن، سینه را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0283":{"name":"شنا سوئدی الماسی","steps":["در حالت پلانک بلند با دست‌های نزدیک هم شروع کنید؛ شست‌ها و اشاره‌ها شکل الماسی بسازند.","بدن را در خطی صاف از سر تا پنجه نگه دارید؛ میان‌تنه و باسن منقبض.","سینه را به سمت شکل الماسی دست‌ها پایین ببرید؛ آرنج‌ها نزدیک بدن.","در پایین‌ترین نقطه مکث کنید، سپس بدن را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0284":{"name":"ساق پا دونکی","steps":["با پنجه‌ها روی سطح بلندتر مثل پله یا بلوک بایستید.","برای تعادل، دست‌ها را روی تکیه‌گاه ثابتی مثل دیوار یا نرده بگذارید.","پاشنه‌ها را تا حد ممکن بالا ببرید و وزن بدن را روی پنجه‌ها بیندازید.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاشنه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1275":{"name":"شنا سوئدی با سقوط","steps":["در حالت پلانک بلند شروع کنید و دست‌ها را کمی بازتر از عرض شانه بگذارید.","سینه را با آرنج‌های نزدیک بدن به سمت زمین پایین ببرید.","وقتی سینه کمی بالای زمین بود، سریع زانوها را به زمین بیندازید.","با صاف‌کردن بازوها خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0285":{"name":"جلوبازو دمبل یک‌درمیان","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف رو به جلو و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","با جابه‌جایی دست‌ها برای تعداد دلخواه تکرار کنید."]},
"2403":{"name":"جلوبازو دمبل یک‌درمیان (با آرم بلاستر)","steps":["صاف با پاهای به عرض شانه بایستید و در هر دست دمبل با کف رو به جلو بگیرید.","آرم بلاستر را روی بازوها قرار دهید و مطمئن شوید محکم باشد.","بازوها ثابت بمانند و همزمان با انقباض جلوبازو و بازدم، یک دمبل به سمت شانه بالا کشیده شود.","دمبل را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","حرکت را با بازوی مخالف تکرار کنید.","به‌تناوب دست‌ها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"1646":{"name":"جلوبازو چکشی لاری یک‌درمیان دمبل","steps":["روی میز لاری با دمبل در هر دست بنشینید؛ کف دست‌ها رو به تنه و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","تعداد تکرار توصیه‌شده را انجام دهید."]},
"1647":{"name":"جلوبازو لاری یک‌درمیان دمبل","steps":["روی میز لاری با دمبل در هر دست و کف رو به بالا بنشینید.","بازوها را روی پد میز لاری بگذارید و اجازه دهید بازوها کاملاً صاف شوند.","بازوها ثابت بمانند و همزمان با انقباض جلوبازو و بازدم، دمبل دست راست بالا کشیده شود.","جلوبازو را ادامه دهید تا جلوبازو کاملاً منقبض و دمبل هم‌سطح شانه شود.","لحظه‌ای مکث کنید، سپس نفس بگیرید و دمبل را به‌آرامی به موقعیت شروع برگردانید.","حرکت را با بازوی چپ تکرار کنید.","به‌تناوب دست‌ها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"1648":{"name":"جلوبازو چکشی نشسته یک‌درمیان دمبل","steps":["روی میز با دمبل در هر دست بنشینید؛ کف دست‌ها رو به تنه و بازوها رو به پایین دراز.","کمر را صاف و آرنج‌ها را نزدیک تنه نگه دارید.","بازدم کنید و دمبل دست راست را با بازوی ثابت به سمت شانه بکشید.","دمبل را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","مکث کوتاهی کنید، سپس نفس بگیرید و دمبل را به‌آرامی به موقعیت شروع برگردانید.","حرکت را با بازوی چپ تکرار کنید.","به‌تناوب دست‌ها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"0286":{"name":"پرس از پهلو دمبل یک‌درمیان","steps":["با پاهای به عرض شانه بایستید؛ دمبل در هر دست هم‌سطح شانه.","یک دمبل را از بالای سر پرس کنید و دمبل دیگر هم‌سطح شانه بماند.","دمبلِ پرس‌شده را هم‌سطح شانه پایین بیاورید و همزمان دمبل دیگر را از بالای سر پرس کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"1649":{"name":"جلوبازو یک‌درمیان دمبل با پا بلند روی توپ سوئیسی","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","توپ ورزشی را پشت سر بگذارید، یک پا را روی آن قرار دهید و تعادل را حفظ کنید.","با بازوهای کاملاً صاف و آرنج‌های نزدیک پهلوها، یک دمبل را با بازوی ثابت به سمت شانه بکشید.","دمبل را به موقعیت شروع برگردانید و با دست دیگر تکرار کنید.","به‌تناوب دست‌ها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"1650":{"name":"جلوبازو نشسته یک‌درمیان دمبل روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو و بازوها کاملاً صاف.","بازوها ثابت بمانند و همزمان با بازدم، یک دمبل با چرخاندن ساعد بالا کشیده شود تا کف دست رو به شانه شود.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","جلوبازو را با دست دیگر تکرار کنید.","جلوبازوهای یک‌درمیان را برای تعداد دلخواه تکرار ادامه دهید."]},
"2137":{"name":"پرس آرنولد دمبل","steps":["روی میز پشتی‌دار بنشینید و در هر دست دمبل را هم‌سطح شانه بگیرید؛ کف رو به بدن و آرنج‌ها خم.","دمبل‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید؛ کف دست‌ها رو به جلو.","مچ‌ها را هنگام بلندکردن بچرخانید تا در بالای حرکت کف دست‌ها رو به جلو شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0287":{"name":"پرس آرنولد دمبل نسخه ۲","steps":["روی میز پشتی‌دار بنشینید و در هر دست دمبل را هم‌سطح شانه بگیرید؛ کف رو به بدن و آرنج‌ها خم.","دمبل‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید؛ کف دست‌ها رو به جلو.","مچ‌ها را هنگام بلندکردن بچرخانید تا در بالای حرکت کف دست‌ها رو به جلو شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0288":{"name":"پول‌اور دایره‌ای دمبل","steps":["روی میز دراز بکشید؛ سر در یک انتها و پاها محکم روی زمین.","دمبل را با هر دو دست بگیرید و بازوها را صاف بالای سینه دراز کنید.","با بازوهای صاف، دمبل را با حرکت قوسی به‌آرامی پشت سر پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0289":{"name":"پرس سینه دمبل","steps":["روی میز به پشت دراز بکشید، کف پاها روی زمین و کمر چسبیده به میز باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو و بازوها بالای سینه دراز.","دمبل‌ها را به‌آرامی کنار سینه پایین ببرید؛ آرنج‌ها با زاویه ۹۰ درجه.","لحظه‌ای مکث کنید، سپس دمبل‌ها را با بازوهای کاملاً صاف به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0290":{"name":"پرس سرشانه نشسته دمبل","steps":["روی میز با دمبل در هر دست بنشینید؛ روی ران‌ها بگذارید.","به عقب خم شوید و دمبل‌ها را کنار سینه با کف دست‌ها رو به جلو قرار دهید.","دمبل‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0291":{"name":"اسکوات روی میز دمبل","steps":["دمبل را روی زمین جلوی میز قرار دهید.","پشت به میز با پاهای به عرض شانه بایستید.","از زانو و لگن خم شوید و به سمت میز پایین بروید؛ سینه بالا و کمر صاف.","وقتی باسن به میز رسید، با فشار پاشنه‌ها به موقعیت شروع بلند شوید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0293":{"name":"زیربغل خم دمبل","steps":["با پاهای به عرض شانه، زانوهای کمی خم بایستید و در هر دست دمبل با کف رو به بدن بگیرید.","از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را منقبض نگه دارید.","اجازه دهید بازوها با کمی خم در آرنج به سمت زمین آویزان باشند.","دمبل‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1651":{"name":"جلوبازو دمبل با لانژ و حرکت بولینگ","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","با پای راست به جلو قدم بردارید؛ زانوی راست خم و بدن به حالت لانژ پایین.","همزمان با لانژ رو به جلو، دمبل‌ها را با آرنج‌های نزدیک بدن به سمت شانه‌ها بالا بکشید.","در پایین‌ترین نقطه لانژ، تنه را مثل پرتاب بولینگ به راست بچرخانید.","حرکت را برعکس کنید؛ با گام پای راست به عقب به موقعیت شروع برگردید و دمبل‌ها را پایین بیاورید.","لانژ و جلوبازو را تکرار کنید؛ این‌بار تنه را به چپ بچرخانید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"1652":{"name":"جلوبازو دمبل روی توپ سوئیسی با پا بلند","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو و بازوها کاملاً صاف.","دمبل‌ها را با آرنج‌های نزدیک پهلوها به‌آرامی به سمت شانه‌ها بکشید.","در بالای حرکت مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","همزمان با جلوبازو، یک پا را از زمین بلند کنید و در طول حرکت در هوا نگه دارید.","برای تعداد دلخواه تکرار کنید، سپس پاها را عوض کنید و دوباره تکرار کنید."]},
"1653":{"name":"جلوبازو دمبل با حالت لک‌لک","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","یک پا را پشت سر دراز کنید و روی پنجه همان پا تعادل بگیرید.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس پاها را عوض کنید و دوباره تکرار کنید."]},
"0294":{"name":"جلوبازو دمبل","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف رو به جلو و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2401":{"name":"جلوبازو دمبل (با آرم بلاستر)","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.","بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1654":{"name":"جلوبازو برعکس دمبل","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف رو به پایین و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1655":{"name":"جلوبازو دمبل با اسکوات","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","با کمر صاف و آرنج‌های نزدیک پهلوها، بازدم کنید و دمبل‌ها را به سمت شانه‌ها بالا بکشید.","در بالای حرکت مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1656":{"name":"جلوبازو دمبل روی بوسو با حالت V","steps":["روی نیم‌توپ بوسو بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو و بازوها صاف کنار بدن.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1201":{"name":"برپی با دمبل","steps":["در حالت ایستاده با پاهای به عرض شانه و دمبل در هر دست شروع کنید.","بدن را به حالت اسکوات پایین ببرید و دمبل‌ها را جلوی خود روی زمین بگذارید.","پاها را به حالت شنا سوئدی به عقب پرت کنید؛ بدن در خطی صاف.","یک شنا سوئدی انجام دهید؛ آرنج‌ها خم و سینه به سمت زمین.","پاها را به سمت دست‌ها بپرید و در حالت اسکوات فرود بیایید.","با انفجار بلند شوید؛ دمبل‌ها را از زمین بردارید و به شانه‌ها بیاورید.","دمبل‌ها را با بازوهای کاملاً صاف از بالای سر پرس کنید.","دمبل‌ها را به شانه‌ها برگردانید و کل توالی را برای تعداد دلخواه تکرار کنید."]},
"0295":{"name":"کلین دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل را با دست از پشت بگیرید.","زانوها را خم کنید و با کمر صاف و سینه بالا لگن را به حالت اسکوات پایین ببرید.","با فشار انفجاری پاشنه‌ها، لگن و زانوها را صاف کنید و از زمین بپرید.","همزمان با پرش، شانه‌ها را بالا بیندازید و دمبل‌ها را نزدیک بدن به سمت شانه‌ها بکشید.","دمبل‌ها را هم‌سطح شانه بگیرید؛ آرنج‌ها رو به جلو و کف دست‌ها رو به بالا.","دمبل‌ها را با برعکس‌کردن حرکت به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1731":{"name":"پرس دست جمع دمبل","steps":["روی میز صاف بنشینید و در هر دست دمبل بگیرید؛ روی ران‌ها بگذارید.","با کمک ران‌ها دمبل‌ها را یکی‌یکی بلند کنید تا در مقابل خود و به عرض شانه نگه‌شان دارید.","وقتی دست‌ها به عرض شانه رسیدند، مچ‌ها را رو به جلو بچرخانید تا کف دست‌ها رو به بیرون شود؛ این موقعیت شروع شماست.","با دم، دمبل‌ها را به‌آرامی به پهلو پایین ببرید تا تقریباً هم‌سطح سینه شوند.","با بازدم، پشت‌بازو را منقبض کنید و دمبل‌ها را به موقعیت شروع برگردانید؛ فقط از پشت‌بازو استفاده کنید و ساعد یا جلوبازو را درگیر نکنید.","بعد از مکث دوم در حالت انقباضی، حرکت را برای تعداد تکرار توصیه‌شده ادامه دهید."]},
"0296":{"name":"پرس دست جمع دمبل","steps":["روی میز صاف بنشینید و در هر دست دمبل بگیرید؛ روی ران‌ها بگذارید.","با کمک ران‌ها دمبل‌ها را یکی‌یکی بلند کنید تا در مقابل خود و به عرض شانه نگه‌شان دارید.","وقتی دست‌ها به عرض شانه رسیدند، مچ‌ها را رو به جلو بچرخانید تا کف دست‌ها رو به بیرون شود؛ این موقعیت شروع شماست.","با دم، دمبل‌ها را به‌آرامی به پهلو پایین ببرید تا تقریباً هم‌سطح سینه شوند.","با بازدم، پشت‌بازو را منقبض کنید و دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0297":{"name":"جلوبازو تمرکزی دمبل","steps":["با پاهای باز روی میز بنشینید و دمبل را در یک دست بگیرید؛ آرنج روی داخل ران.","بازو را کاملاً دراز کنید و دمبل را با دست از جلو بگیرید.","بازو ثابت بماند و همزمان با انقباض جلوبازو و بازدم، وزنه به سمت شانه بالا کشیده شود.","دمبل را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"3635":{"name":"لانژ رو به جلو ضربدری دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","با پای راست به جلو قدم بردارید؛ کمر صاف و میان‌تنه منقبض.","بدن را با خم‌کردن هر دو زانو پایین ببرید تا ران راست موازی زمین شود.","با فشار پاشنه پای راست به موقعیت شروع برگردید.","حرکت را با پای چپ تکرار کنید.","پاها را برای تعداد دلخواه تکرار یک‌درمیان عوض کنید."]},
"0298":{"name":"جلوبازو چکشی ضربدری دمبل","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.","بازدم کنید و با انقباض جلوبازو وزنه‌ها را ضربدری به سمت شانه مخالف بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1657":{"name":"جلوبازو چکشی ضربدری دمبل نسخه ۲","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.","بازدم کنید و با انقباض جلوبازو وزنه‌ها را تا حد ممکن نزدیک شانه مخالف بکشید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0299":{"name":"پرس کوبایی دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل را هم‌سطح شانه بگیرید؛ کف رو به پایین.","با میان‌تنه منقبض و آرنج‌های کمی خم، دمبل‌ها را بالا و از بالای سر پرس کنید تا بازوها کاملاً صاف شوند.","مچ‌ها را بچرخانید تا کف دست‌ها رو به جلو شوند.","دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید و همزمان مچ‌ها را به حالت اولیه بچرخانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2136":{"name":"پرس کوبایی دمبل نسخه ۲","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل را هم‌سطح شانه بگیرید؛ کف رو به پایین.","با میان‌تنه منقبض و کمر صاف، دمبل‌ها را صاف از بالای سر پرس کنید تا بازوها کاملاً صاف شوند.","مچ‌ها را بچرخانید تا کف دست‌ها رو به جلو شوند.","دمبل‌ها را هم‌سطح شانه پایین ببرید و مچ‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0300":{"name":"ددلیفت دمبل","steps":["بایستید، پاها به عرض شانه و پنجه‌ها رو به جلو.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن و بازوها رو به پایین دراز.","از لگن و زانو خم شوید و دمبل‌ها را با کمر صاف به سمت زمین پایین ببرید.","با فشار پاشنه‌ها و صاف‌کردن لگن و زانوها، دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0301":{"name":"پرس زیرسینه دمبل","steps":["روی میز زیرسینه دراز بکشید؛ پاها ثابت و سر پایین‌تر از لگن.","در هر دست دمبل بگیرید و بازوها را صاف بالای سینه دراز کنید؛ کف دست‌ها رو به جلو.","دمبل‌ها را به‌آرامی کنار سینه پایین ببرید؛ آرنج‌ها با زاویه ۹۰ درجه.","دمبل‌ها را با بازوهای کاملاً صاف به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0302":{"name":"قفسه زیرسینه دمبل","steps":["روی میز زیرسینه دراز بکشید؛ پاها ثابت و سر پایین‌تر از لگن.","در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها بالای سینه صاف.","دمبل‌ها را در قوسی باز به طرفین پایین ببرید تا کشش را در سینه احساس کنید.","لحظه‌ای مکث کنید، سپس با انقباض عضلات سینه دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0303":{"name":"پرس چکشی زیرسینه دمبل","steps":["روی میز زیرسینه دراز بکشید؛ پاها ثابت و سر پایین‌تر از لگن.","در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها بالای سینه صاف.","دمبل‌ها را کنار سینه با کمی خم در آرنج‌ها پایین ببرید.","دمبل‌ها را با بازوهای کاملاً صاف به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1276":{"name":"قفسه زیرسینه تک‌دست دمبل","steps":["روی میز زیرسینه دراز بکشید و دمبل را در یک دست روی ران بگذارید.","با کمک ران، دمبل را تا هم‌سطح شانه بالا ببرید؛ کف دست رو به تنه.","مچ را بچرخانید تا کف دست رو به جلو شود.","با دم، دمبل را به‌آرامی به پهلو پایین ببرید تا کشش سینه را احساس کنید.","بازدم کنید و با عضلات سینه دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1617":{"name":"پرس چکشی زیرسینه تک‌دست دمبل","steps":["روی میز زیرسینه دراز بکشید و یک دمبل در یک دست بگیرید؛ روی سینه بگذارید.","بازو را با کمی خم در آرنج صاف به بالا دراز کنید.","دمبل را با آرنج نزدیک بدن به سمت شانه پایین ببرید.","دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0305":{"name":"شراگ زیرسینه دمبل","steps":["میز زیرسینه را روی زاویه ۴۵ درجه تنظیم کنید.","رو به زمین روی میز دراز بکشید؛ سینه و شکم روی میز.","در هر دست دمبل بگیرید و بازوها را کاملاً صاف به سمت زمین دراز کنید.","با بازوهای صاف، شانه‌ها را تا حد ممکن به سمت گوش‌ها بالا ببرید.","انقباض را لحظه‌ای نگه دارید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0304":{"name":"شراگ زیرسینه دمبل نسخه ۲","steps":["میز زیرسینه را روی زاویه ۴۵ درجه تنظیم کنید.","رو به زمین روی میز دراز بکشید؛ سینه و شکم روی میز.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها کاملاً دراز.","با بازوهای صاف، شانه‌ها را تا حد ممکن بالا ببرید و کتف‌ها را به هم فشار دهید.","انقباض را لحظه‌ای نگه دارید، سپس دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0306":{"name":"پشت‌بازو زیرسینه دمبل","steps":["روی میز زیرسینه دراز بکشید؛ سر پایین‌تر از پا و در هر دست دمبل با کف دست‌ها رو به هم.","بازوها را با آرنج‌های نزدیک سر کاملاً دراز کنید.","دمبل‌ها را با خم‌کردن آرنج‌ها به‌آرامی پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0307":{"name":"قفسه چرخشی زیرسینه دمبل","steps":["روی میز زیرسینه دراز بکشید؛ سر پایین‌تر از لگن.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها صاف روی سینه دراز.","دمبل‌ها را در قوسی باز به طرفین پایین ببرید تا کشش را در سینه احساس کنید.","همزمان با پایین‌بردن دمبل‌ها مچ‌ها را بچرخانید تا در پایین حرکت کف دست‌ها رو به جلو شوند.","حرکت را برعکس کنید و دمبل‌ها را به موقعیت شروع برگردانید؛ در بالا عضلات سینه منقبض.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1437":{"name":"جلوبازو انگشتان دمبل","steps":["روی میز یا صندلی بنشینید؛ کف پاها صاف روی زمین و کمر صاف.","دمبل را در یک دست با دست از جلو بگیرید و ساعد را روی ران بگذارید؛ کف دست رو به بالا.","اجازه دهید دمبل تا نوک انگشتان پایین برود، سپس با خم‌کردن انگشتان آن را بالا بکشید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0308":{"name":"قفسه سینه دمبل","steps":["روی میز به پشت دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","بازوها را با کمی خم در آرنج‌ها صاف روی سینه دراز کنید.","با کمی خم در آرنج‌ها، بازوها را در قوسی باز به طرفین پایین ببرید تا کشش سینه را احساس کنید.","لحظه‌ای مکث کنید، سپس حرکت را برعکس کنید و دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1277":{"name":"قفسه سینه دمبل روی توپ سوئیسی","steps":["روی توپ ورزشی بنشینید و در هر دست دمبل بگیرید.","پاها را به جلو حرکت دهید و بدن را پایین غلتانید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","بازوها را صاف بالای سینه دراز کنید؛ کف دست‌ها رو به هم.","آرنج‌ها را کمی خم کنید و بازوها را در قوسی باز به طرفین پایین ببرید تا کشش سینه را احساس کنید.","لحظه‌ای مکث کنید، سپس حرکت را برعکس کنید و همزمان با برگرداندن دمبل‌ها عضلات سینه را منقبض کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1732":{"name":"لانژ رو به جلو با پشت‌بازو دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","با پای راست یک قدم به جلو بردارید و بدن را به حالت لانژ پایین ببرید.","کمر را صاف و سینه را بالا نگه دارید.","بازوها را با آرنج‌های نزدیک گوش صاف بالای سر دراز کنید.","دمبل‌ها را با خم‌کردن آرنج‌ها پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس برای برگشتن به موقعیت شروع بازوها را صاف کنید.","حرکت را برای تعداد دلخواه تکرار کنید، سپس پاها را عوض و دوباره تکرار کنید."]},
"0310":{"name":"نشر از جلو دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به ران‌ها.","با بازوهای صاف، بازدم کنید و دمبل‌ها را در مقابل خود تا هم‌سطح شانه بالا ببرید.","در بالای حرکت مکث کنید، سپس نفس بگیرید و دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0309":{"name":"نشر از جلو دمبل نسخه ۲","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به ران‌ها.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دمبل‌ها را با بازوهای صاف به‌آرامی جلوی خود بالا ببرید تا هم‌سطح شانه شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0311":{"name":"نشر جانب با حالت فول‌کن دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1760":{"name":"گابلِت اسکوات دمبل","steps":["با پاهای به عرض شانه بایستید و دمبل را عمودی با هر دو دست به سینه بچسبانید.","با سینه بالا و میان‌تنه منقبض، با عقب‌بردن لگن و خم‌کردن زانوها بدن را به حالت اسکوات پایین ببرید.","به پایین‌کردن ادامه دهید تا ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.","در پایین‌ترین نقطه مکث کنید، سپس با فشار پاشنه‌ها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0313":{"name":"جلوبازو چکشی دمبل","steps":["صاف بایستید و در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به تنه باشد.","آرنج‌ها را نزدیک تنه نگه دارید و کف دست‌ها را بچرخانید تا رو به جلو شوند.","این موقعیت شروع شماست.","اکنون با ثابت‌نگه‌داشتن بازوها، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","سپس نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","تعداد تکرار توصیه‌شده را انجام دهید."]},
"1659":{"name":"جلوبازو چکشی دمبل روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو دمبل‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0312":{"name":"جلوبازو چکشی دمبل نسخه ۲","steps":["صاف بایستید و در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به تنه باشد.","آرنج‌ها را نزدیک تنه نگه دارید و کف دست‌ها را بچرخانید تا رو به جلو شوند.","این موقعیت شروع شماست.","اکنون با ثابت‌نگه‌داشتن بازوها، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","سپس نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","تعداد تکرار توصیه‌شده را انجام دهید."]},
"2402":{"name":"جلوبازو چکشی دمبل (با آرم بلاستر)","steps":["صاف بایستید و در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به تنه باشد.","آرنج‌ها را نزدیک تنه نگه دارید و کف دست‌ها را بچرخانید تا رو به جلو شوند.","این موقعیت شروع شماست.","اکنون با بازوهای ثابت، همزمان با انقباض جلوبازو و بازدم وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","سپس نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","تعداد تکرار توصیه‌شده را انجام دهید."]},
"1664":{"name":"جلوبازو بلند دمبل","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","بازوها ثابت بمانند و دمبل‌ها با انقباض جلوبازو تا حد ممکن بالا کشیده شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3545":{"name":"پرس بالاسینه یک‌درمیان دمبل","steps":["روی میز بالاسینه بنشینید و در هر دست دمبل بگیرید؛ روی ران‌ها بگذارید.","به عقب روی میز تکیه دهید و برای بالابردن دمبل‌ها تا هم‌سطح شانه از ران‌ها کمک بگیرید؛ کف دست‌ها رو به جلو.","وقتی هم‌سطح شانه رسیدید، مچ‌ها را بچرخانید تا کف دست‌ها رو به جلو شوند.","دمبل‌ها را با سینه و سرشانه و بازوهای کاملاً صاف به بالا پرس کنید.","دمبل‌ها را با کمی خم در آرنج‌ها به موقعیت شروع برگردانید.","با جابه‌جایی دست‌ها برای تعداد دلخواه تکرار کنید."]},
"0314":{"name":"پرس بالاسینه دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی میز با کف پاها صاف روی زمین و کمر محکم چسبیده به میز بنشینید.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو و تا هم‌سطح شانه بلند کنید.","دمبل‌ها را کنار سینه با آرنج‌های ۹۰ درجه به‌آرامی پایین ببرید.","دمبل‌ها را با بازوهای کاملاً صاف به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0315":{"name":"جلوبازو بالاسینه دمبل","steps":["روی میز بالاسینه با دمبل در هر دست بنشینید؛ کف رو به جلو و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0316":{"name":"قفسه بالاسینه دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی میز بنشینید؛ کمر به پد چسبیده و کف پاها صاف روی زمین.","در هر دست دمبل را با دست از پشت و کف رو به جلو بگیرید.","با بازوهای کاملاً صاف و عمود بر زمین شروع کنید.","دمبل‌ها را به‌آرامی کنار سینه پایین ببرید؛ آرنج‌ها با زاویه ۹۰ درجه.","در پایین‌ترین نقطه مکث کنید، سپس دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0318":{"name":"جلوبازو بالاسینه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با دمبل در هر دست و کف رو به جلو بنشینید.","بازوها را روی میز بالاسینه بگذارید؛ آرنج‌ها آویزان و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0317":{"name":"جلوبازو بالاسینه دمبل نسخه ۲","steps":["روی میز بالاسینه با دمبل در هر دست بنشینید؛ کف رو به جلو و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0319":{"name":"قفسه بالاسینه دمبل","steps":["میز بالاسینه را روی زاویه ۴۵ درجه تنظیم کنید.","روی میز بنشینید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","به عقب روی میز دراز بکشید و دمبل‌ها را دقیقاً بالای سینه به موقعیت شروع پرس کنید.","دمبل‌ها را در قوسی باز به طرفین پایین ببرید تا کشش را در سینه احساس کنید.","لحظه‌ای مکث کنید، سپس با انقباض عضلات سینه دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1278":{"name":"قفسه بالاسینه دمبل روی توپ سوئیسی","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی توپ ورزشی بنشینید و به جلو غلتانید تا پشت بالایی روی میز بالاسینه باشد.","در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها بالای سینه صاف.","دمبل‌ها را در قوسی باز به طرفین پایین ببرید تا کشش را در سینه احساس کنید.","لحظه‌ای مکث کنید، سپس با انقباض عضلات سینه دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0320":{"name":"جلوبازو چکشی بالاسینه دمبل","steps":["روی میز بالاسینه با دمبل در هر دست بنشینید؛ کف رو به تنه و بازوها کاملاً صاف.","کمر چسبیده به میز و کف پاها صاف روی زمین بماند.","بازوها ثابت بمانند و همزمان با انقباض جلوبازو و بازدم، وزنه‌ها بالا کشیده شوند.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0321":{"name":"پرس چکشی بالاسینه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با دمبل در هر دست روی ران‌ها بنشینید.","به عقب روی میز دراز بکشید و دمبل‌ها را هم‌سطح شانه با کف دست‌ها رو به هم قرار دهید.","دمبل‌ها را از بدن دور تا صاف‌شدن کامل بازوها پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1618":{"name":"پرس چکشی بالاسینه تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","پاها را به جلو حرکت دهید و بدن را روی توپ پایین بیاورید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","دمبل‌ها را هم‌سطح شانه بگیرید؛ آرنج‌ها خم و رو به طرفین.","دمبل‌ها را با کمی زاویه به داخل و کف دست‌ها رو به هم پرس کنید.","بازوها را کاملاً دراز کنید و در بالای حرکت پشت‌بازو را منقبض کنید.","دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0322":{"name":"جلوبازو داخلی بالاسینه دمبل","steps":["روی میز بالاسینه با دمبل در هر دست و کف دست‌ها رو به هم بنشینید.","بازوها را روی میز بگذارید؛ آرنج‌ها آویزان و کف دست‌ها رو به جلو.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1279":{"name":"قفسه بالاسینه تک‌دست دمبل","steps":["میز بالاسینه را روی زاویه ۳۰ تا ۴۵ درجه تنظیم کنید.","روی میز با دمبل در یک دست بنشینید؛ روی ران بگذارید.","به عقب روی میز دراز بکشید؛ کف پاها صاف روی زمین.","دمبل را با بازوی صاف روی سینه نگه دارید.","دمبل را در قوسی باز به پهلو پایین ببرید و آرنج را کمی خم نگه دارید.","وقتی بازو موازی زمین شد مکث کنید، سپس حرکت را برعکس کنید و دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1280":{"name":"قفسه بالاسینه تک‌دست دمبل روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید و یک دمبل در یک دست بگیرید.","پاها را به جلو حرکت دهید و بدن را پایین غلت دهید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","دمبل را با بازوی صاف روی سینه نگه دارید؛ کف دست رو به داخل.","دمبل را به‌آرامی به پهلو پایین ببرید و آرنج را کمی خم نگه دارید.","وقتی بازو موازی زمین شد لحظه‌ای مکث کنید.","با انقباض عضلات سینه، دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1619":{"name":"پرس چکشی بالاسینه تک‌دست دمبل","steps":["روی میز بالاسینه بنشینید و دمبل را در یک دست روی ران بگذارید.","به عقب روی میز تکیه دهید و برای بالابردن دمبل تا هم‌سطح شانه از ران کمک بگیرید.","مچ را بچرخانید تا کف دست رو به داخل و سمت بدن شود.","دمبل را از بدن دور و با دراز‌کردن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1620":{"name":"پرس چکشی بالاسینه تک‌دست دمبل روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید و یک دمبل در یک دست بگیرید.","پاها را به جلو حرکت دهید و بدن را پایین غلت دهید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","دمبل را با کف دست رو به داخل بگیرید؛ آرنج با زاویه ۹۰ درجه خم.","دمبل را با صاف‌کردن بازو به سمت سقف پرس کنید.","دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0323":{"name":"نشر جانب تک‌دست بالاسینه دمبل","steps":["روی میز بالاسینه با دمبل در یک دست بنشینید؛ روی ران بگذارید.","به جلو خم شوید و بازو را داخل ران تکیه دهید.","دمبل را با کمی خم در بازو و کف رو به پایین به پهلو بالا ببرید.","بلندکردن را ادامه دهید تا بازو موازی زمین شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1281":{"name":"پرس بالاسینه تک‌دست دمبل","steps":["روی میز بالاسینه بنشینید و دمبل را در یک دست روی ران بگذارید.","به عقب روی میز دراز بکشید و دمبل را هم‌سطح شانه با کف رو به جلو قرار دهید.","دمبل را با کمی زاویه به داخل و دراز‌کردن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1282":{"name":"پرس بالاسینه تک‌دست دمبل روی توپ سوئیسی","steps":["روی توپ ورزشی با دمبل در یک دست بنشینید؛ کف پاها صاف روی زمین.","پاها را به‌آرامی به جلو حرکت دهید و توپ را غلتانید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","دمبل را هم‌سطح شانه با کف دست رو به جلو نگه دارید.","دمبل را تا صاف‌شدن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0324":{"name":"پرس بالاسینه با کف رو به داخل دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی میز بنشینید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","پاها را محکم روی زمین بگذارید و کمر صاف به میز چسبیده باشد.","با دمبل‌ها هم‌سطح شانه، آرنج‌های خم و کف دست‌ها رو به هم شروع کنید.","دمبل‌ها را از بدن دور با بازوهای کاملاً صاف پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1283":{"name":"پرس بالاسینه دمبل روی توپ سوئیسی","steps":["روی توپ ورزشی با دمبل در هر دست بنشینید؛ کف دست‌ها رو به جلو.","پاها را به‌آرامی به جلو حرکت دهید و بدن را روی توپ پایین بیاورید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","دمبل‌ها را هم‌سطح شانه بگیرید؛ آرنج‌ها خم و رو به طرفین.","دمبل‌ها را با دراز‌کردن کامل بازوها به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0325":{"name":"نشر بالاسینه دمبل","steps":["روی میز بالاسینه بنشینید و در هر دست دمبل بگیرید؛ روی ران‌ها بگذارید.","به عقب روی میز تکیه دهید و دمبل‌ها را هم‌سطح شانه با کف رو به جلو بالا ببرید.","با کمر چسبیده به میز، بازدم کنید و دمبل‌ها را با بازوهای کاملاً صاف بالای سر ببرید.","در بالای حرکت مکث کنید، سپس نفس بگیرید و دمبل‌ها را به‌آرامی تا هم‌سطح شانه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0326":{"name":"نشر خلفی بالاسینه دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی میز با سینه چسبیده به پشتی بنشینید و در هر دست دمبل بگیرید.","بازوها را صاف به پایین دراز کنید؛ کف دست‌ها رو به هم.","با کمی خم در آرنج‌ها، بازوها را به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0327":{"name":"زیربغل بالاسینه دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","در هر دست دمبل بگیرید و روی میز بنشینید؛ سینه چسبیده به شیب.","بازوها را کاملاً دراز کنید و اجازه دهید دمبل‌ها صاف از شانه‌ها آویزان باشند.","دمبل‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0328":{"name":"نشر بالاسینه سرشانه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با دمبل در هر دست و کف رو به پایین بنشینید.","دمبل‌ها را روی ران‌ها بگذارید و به عقب روی میز تکیه دهید.","برای بالابردن دمبل‌ها تا هم‌سطح شانه از ران‌ها کمک بگیرید، سپس مچ‌ها را بچرخانید تا کف دست‌ها رو به جلو شوند.","بازدم کنید و دمبل‌ها را با کمی خم در آرنج‌ها به‌آرامی بالای سر ببرید.","در بالای حرکت مکث کنید، سپس نفس بگیرید و دمبل‌ها را به‌آرامی تا هم‌سطح شانه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0329":{"name":"شراگ بالاسینه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با یک دمبل در هر دست روی آن بنشینید.","کف پاها صاف روی زمین و بازوها با کف رو به بدن صاف آویزان باشد.","با بازوهای صاف، شانه‌ها را تا حد ممکن به سمت گوش‌ها شراگ بزنید.","انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3542":{"name":"نشر T بالاسینه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با یک دمبل در هر دست و کف رو به داخل روی آن بنشینید.","به جلو خم شوید و اجازه دهید بازوها صاف و عمود بر زمین آویزان باشند.","با بازوهای صاف، آنها را به طرفین بالا ببرید تا موازی زمین شوند و بدن حالت T بگیرد.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0330":{"name":"پشت‌بازو بالاسینه دمبل","steps":["روی میز بالاسینه با دمبل در هر دست و کف رو به داخل بنشینید.","بازوها را با آرنج‌های نزدیک سر کاملاً بالای سر دراز کنید.","دمبل‌ها را با خم‌کردن آرنج‌ها و بازوهای ثابت پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس با دراز‌کردن بازوها دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0331":{"name":"قفسه چرخشی بالاسینه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با دمبل در هر دست و کف دست‌ها رو به هم بنشینید.","به عقب روی میز دراز بکشید و دمبل‌ها را با بازوهای دراز دقیقاً بالای سینه به موقعیت شروع پرس کنید.","دمبل‌ها را در قوسی باز به طرفین پایین ببرید تا کشش را در سینه احساس کنید.","همزمان با پایین‌بردن دمبل‌ها مچ‌ها را بچرخانید تا در پایین حرکت کف دست‌ها رو به جلو شوند.","حرکت را برعکس کنید و دمبل‌ها را به موقعیت شروع برگردانید؛ در بالا عضلات سینه به هم فشار داده شوند.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1733":{"name":"پشت‌بازو دو دست بالاسینه دمبل","steps":["روی میز بالاسینه بنشینید و در هر دست دمبل بگیرید؛ روی ران‌ها بگذارید.","به‌آرامی به عقب روی میز دراز بکشید و دمبل‌ها را نزدیک سینه نگه دارید.","وقتی کاملاً دراز کشیدید، بازوها را با کمی خم در آرنج صاف به سمت سقف دراز کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3541":{"name":"نشر Y بالاسینه دمبل","steps":["میز را روی زاویه ۴۵ درجه تنظیم کنید و با یک دمبل در هر دست و کف رو به داخل روی آن بنشینید.","کمی به جلو خم شوید و اجازه دهید بازوها با کمی خم در آرنج صاف آویزان باشند.","بازوها را به‌صورت Y به طرفین و بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0332":{"name":"صلیب آهنین دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل کنار بدن.","بازوها را به طرفین بالا ببرید تا موازی زمین شوند و بدن حالت T بگیرد.","لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0333":{"name":"کیک‌بک پشت‌بازو دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","بازوها را نزدیک پهلوها ببرید؛ آرنج‌ها با زاویه ۹۰ درجه خم.","بازوها را صاف به عقب دراز کنید و در اوج حرکت پشت‌بازو را منقبض کنید.","لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1734":{"name":"کیک‌بک پشت‌بازو دمبل روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به داخل و بازوها با زاویه ۹۰ درجه خم.","بازوها را صاف به عقب دراز کنید و در اوج حرکت پشت‌بازو را منقبض کنید.","لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1660":{"name":"جلوبازو زانوزده دمبل روی توپ سوئیسی","steps":["روی زمین زانو بزنید و توپ ورزشی جلوی شما باشد.","آرنج‌ها را روی توپ ورزشی بگذارید و در هر دست دمبل با کف رو به بالا بگیرید.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو دمبل‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0334":{"name":"نشر جانب دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0335":{"name":"نشر جانب به از جلو دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","سپس بازوها را جلوی خود بالا ببرید تا موازی زمین شوند؛ باز هم با کمی خم در آرنج‌ها.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0336":{"name":"لانژ دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","با پای راست یک قدم به جلو بردارید و بدن را به حالت لانژ پایین ببرید.","همزمان با پایین‌بردن بدن، کمر صاف و سینه بالا بماند.","با فشار پاشنه پای راست به موقعیت شروع برگردید.","حرکت را با پای چپ تکرار کنید.","پاها را برای تعداد دلخواه تکرار یک‌درمیان عوض کنید."]},
"1658":{"name":"لانژ با جلوبازو دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","با پای راست به جلو قدم بردارید و بدن را به حالت لانژ پایین ببرید؛ زانوی راست ۹۰ درجه و زانوی چپ کمی بالای زمین.","همزمان با لانژ رو به جلو، دمبل‌ها را با آرنج‌های نزدیک بدن به سمت شانه‌ها بکشید.","در پایین‌ترین نقطه لانژ مکث کنید، سپس با فشار پاشنه راست به موقعیت شروع برگردید و دمبل‌ها را کنار بدن پایین بیاورید.","لانژ و جلوبازو را در طرف مخالف با گام پای چپ به جلو تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0337":{"name":"پشت‌بازو خوابیده دمبل (روی صورت)","steps":["روی میز به پشت دراز بکشید، کف پاها روی زمین و سر در انتهای میز باشد.","دمبل را با هر دو دست بگیرید و بازوها را صاف بالای سینه دراز کنید؛ کف دست‌ها رو به هم.","بازوها ثابت بمانند و دمبل با حرکت قوسی به‌آرامی پشت سر پایین برود تا ساعدها موازی زمین شوند.","لحظه‌ای مکث کنید، سپس با انقباض پشت‌بازو دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1729":{"name":"پشت‌بازو خوابیده یک‌درمیان دمبل","steps":["روی میز به پشت دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","بازوها را با کمی خم در آرنج‌ها صاف روی سینه دراز کنید.","یک دمبل را با خم‌کردن آرنج به سمت سر پایین ببرید؛ بازوی دیگر دراز بماند.","در پایین‌ترین نقطه مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","با دست دیگر تکرار کنید و برای تعداد دلخواه بین طرفین جابه‌جا شوید."]},
"0338":{"name":"پرس آرنج خوابیده دمبل","steps":["روی میز دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها صاف روی سینه.","دمبل‌ها را با خم‌کردن آرنج‌ها و بازوهای ثابت به سمت شانه‌ها پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس دمبل‌ها را با صاف‌کردن آرنج‌ها به موقعیت شروع پرس کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0863":{"name":"چرخش خارجی سرشانه خوابیده دمبل","steps":["به پهلو روی میز صاف دراز بکشید؛ بازوی بالایی کنار بدن و آرنج ۹۰ درجه خم.","دمبل را در دست با کف رو به پایین بگیرید.","بازو کنار بدن بچسبد و ساعد به‌آرامی تا حد ممکن به بالا بچرخد.","در بالای حرکت مکث کنید، سپس ساعد را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0339":{"name":"همسترینگ خوابیده با دمبل","steps":["به پشت دراز بکشید؛ پاها دراز و دمبل روی پایین‌تنه.","زانوها را خم کنید و دمبل را به سمت باسن بیاورید؛ کف پاها صاف روی زمین.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0340":{"name":"پرس چکشی خوابیده دمبل","steps":["روی میز دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم و بازوها صاف بالا.","دمبل‌ها را کنار سینه با آرنج‌های ۹۰ درجه پایین ببرید.","دمبل‌ها را با بازوهای کاملاً صاف به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2470":{"name":"نشر خلفی روی زمین دمبل","steps":["رو به زمین روی زمین دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","بازوها را با کمی خم در آرنج‌ها صاف جلوی خود دراز کنید.","با انقباض عضلات سرشانه، بازوها را بالا و به طرفین ببرید؛ کتف‌ها به هم فشار داده شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0341":{"name":"نشر خلفی خوابیده تک‌دست دمبل","steps":["رو به زمین روی میز صاف دراز بکشید و دمبل را در یک دست با کف رو به داخل بگیرید.","بازو را صاف و نزدیک بدن به سمت زمین دراز کنید.","بازو را بالا و به عقب ببرید و کتف را به سمت ستون فقرات منقبض کنید.","در بالای حرکت مکث کنید، سپس بازو را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0343":{"name":"پرس سینه خوابیده تک‌دست دمبل","steps":["روی میز دراز بکشید؛ دمبل در یک دست و کف پاها صاف روی زمین.","دمبل را هم‌سطح شانه با کف دست رو به جلو نگه دارید.","دمبل را تا صاف‌شدن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0342":{"name":"پرس سینه خوابیده تک‌دست دمبل نسخه ۲","steps":["روی میز دراز بکشید؛ کمر تکیه‌دار و کف پاها صاف روی زمین.","دمبل را در یک دست با کف رو به پاها بگیرید.","بازو را با کمی خم در آرنج به سمت سقف دراز کنید.","دمبل را با آرنج نزدیک بدن به‌آرامی به سمت سینه پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0344":{"name":"پشت‌بازو خوابیده تک‌دست با کف رو به پایین دمبل","steps":["روی میز دراز بکشید؛ کمر و سر تکیه‌دار و کف پاها صاف روی زمین.","دمبل را در یک دست با کف رو به پایین بگیرید و بازو را صاف بالای شانه دراز کنید.","بازو را ثابت نگه دارید و با خم‌کردن آرنج، دمبل را به‌آرامی پشت سر پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس بازو را صاف کرده و به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0345":{"name":"نشر خلفی خوابیده تک‌دست دمبل","steps":["رو به زمین روی میز صاف دراز بکشید و یک دمبل در یک دست به سمت زمین آویزان باشد.","بازو را صاف نگه دارید و دمبل را از بدن دور به پهلو بلند کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0346":{"name":"پشت‌بازو خوابیده تک‌دست با کف رو به بالا دمبل","steps":["روی میز دراز بکشید؛ کمر و سر تکیه‌دار و کف پاها صاف روی زمین.","دمبل را در یک دست با دست از جلو بگیرید و بازو را صاف بالای شانه دراز کنید.","بازو را ثابت نگه دارید و با خم‌کردن آرنج، دمبل را به‌آرامی پشت سر پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس بازو را صاف کرده و به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0347":{"name":"چرخش ساعد خوابیده دمبل","steps":["سینه رو به پایین روی میز دراز بکشید؛ بازوها صاف رو به پایین و در هر دست دمبل.","کف دست‌ها را بچرخانید تا رو به بالا شوند.","بازوها ثابت بمانند و همزمان با چرخاندن کف دست‌ها رو به پایین و بازدم، دمبل‌ها بالا کشیده شوند.","نفس بگیرید و دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2705":{"name":"چرخش ساعد خوابیده روی زمین دمبل","steps":["رو به پایین روی زمین دراز بکشید؛ بازوها صاف جلوی سر و در هر دست دمبل.","کف دست‌ها را بچرخانید تا رو به پایین و زمین شوند.","با بازوهای صاف، دمبل‌ها را با انقباض ساعدها از زمین بلند کنید.","بلندکردن را ادامه دهید تا ساعدها کاملاً منقبض و دمبل‌ها هم‌سطح شانه شوند.","لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1284":{"name":"پول‌اور خوابیده دمبل روی توپ سوئیسی","steps":["روی توپ ورزشی بنشینید و به جلو غلتانید تا پشت بالایی روی توپ باشد.","دمبل را با هر دو دست بگیرید و بازوها را صاف روی سینه دراز کنید.","دمبل را با بازوهای صاف به‌آرامی پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1328":{"name":"زیربغل نشر خلفی خوابیده دمبل","steps":["رو به زمین روی میز صاف دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به داخل.","بازوها را صاف به سمت زمین دراز کنید و آرنج‌ها را کمی خم نگه دارید.","با انقباض عضلات پشت، دمبل‌ها را به سمت سینه بالا بکشید؛ کتف‌ها به هم فشار داده شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0348":{"name":"نشر خلفی خوابیده دمبل","steps":["رو به زمین روی میز صاف دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","بازوها را صاف به سمت زمین دراز کنید و آرنج‌ها را کمی خم نگه دارید.","با انقباض عضلات سرشانه، بازوها را به پهلو بلند کنید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1735":{"name":"پشت‌بازو خوابیده تک دمبل","steps":["روی میز دراز بکشید؛ دمبل در یک دست و بازو کاملاً صاف بالای سینه.","دمبل را با بازوی ثابت و کنترل کامل به سمت پیشانی پایین ببرید.","در پایین‌ترین نقطه حرکت مکث کوتاهی کنید، سپس بازو را به موقعیت شروع صاف کنید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0349":{"name":"چرخش ساعد رو به بالا خوابیده دمبل","steps":["روی میز دراز بکشید؛ کف پاها صاف روی زمین.","در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به بالا و بازوها کاملاً صاف.","بازوها ثابت بمانند و دمبل‌ها با انقباض ساعدها به سمت شانه‌ها کشیده شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2706":{"name":"چرخش ساعد رو به بالا خوابیده روی زمین دمبل","steps":["به پشت روی زمین دراز بکشید؛ پاها دراز، بازوها کنار بدن و در هر دست دمبل.","کف دست‌ها را رو به بالا بچرخانید؛ آرنج‌ها نزدیک پهلوها.","دمبل‌ها را به‌آرامی به سمت شانه‌ها بکشید و ساعدها را منقبض کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1661":{"name":"جلوبازو به پشت خوابیده دمبل","steps":["روی میز دراز بکشید؛ کمر و سر تکیه‌دار و کف پاها صاف روی زمین.","در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به بالا و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0350":{"name":"جلوبازو به پشت خوابیده دمبل","steps":["روی میز دراز بکشید و در هر دست دمبل بگیرید؛ کف رو به بالا و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0351":{"name":"پشت‌بازو خوابیده دمبل","steps":["روی میز به پشت دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","بازوها را با آرنج‌های نزدیک بدن صاف روی سینه دراز کنید.","دمبل‌ها را با خم‌کردن آرنج‌ها به سمت پیشانی پایین ببرید.","لحظه‌ای مکث کنید، سپس بازوها را صاف کرده و به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1662":{"name":"جلوبازو دست باز خوابیده دمبل","steps":["روی میز دراز بکشید و در هر دست دمبل بگیرید؛ کف رو به بالا و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0352":{"name":"پرس سینه با دست خنثی دمبل","steps":["روی میز به پشت دراز بکشید، کف پاها روی زمین و کمر چسبیده به میز باشد.","در هر دست دمبل را با گریپ خنثی (کف دست‌ها رو به هم) بگیرید و بازوها را صاف روی سینه دراز کنید.","دمبل‌ها را با آرنج‌های نزدیک بدن به‌آرامی به سمت سینه پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس دمبل‌ها را با بازوهای کاملاً صاف به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1285":{"name":"قفسه سینه تک‌دست روی میز دمبل","steps":["روی میز صاف با دمبل در یک دست بنشینید؛ روی ران بگذارید.","به عقب روی میز دراز بکشید و دمبل را چسبیده به ران نگه دارید.","با دست آزاد، دمبل را تا موقعیت شروع بالا بیاورید.","دمبل را دقیقاً بالای شانه با بازوی دراز و کف دست رو به داخل نگه دارید.","دمبل را در قوسی باز به پهلو پایین ببرید و آرنج را کمی خم نگه دارید.","وقتی بازو موازی زمین شد مکث کنید، سپس حرکت را برعکس و دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کرده و دوباره تکرار کنید."]},
"0292":{"name":"زیربغل خم تک‌دست دمبل","steps":["بایستید، پاها به عرض شانه و یک دمبل در یک دست بگیرید؛ کف دست رو به بدن.","زانوها را کمی خم کنید و از لگن به جلو خم شوید؛ کمر صاف و میان‌تنه منقبض.","اجازه دهید دمبل با بازوی کاملاً صاف به سمت زمین آویزان باشد.","دمبل را با آرنج نزدیک بدن و فشار کتف‌ها به هم، به سمت سینه بکشید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"1286":{"name":"قفسه سینه تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، یک دمبل در یک دست و کف پاها صاف روی زمین.","پاها را به جلو حرکت دهید و توپ را غلتانید تا پشت بالایی روی توپ و سر، گردن و شانه‌ها بیرون باشند.","بازو را با دمبل صاف بالای سینه دراز کنید؛ کف دست رو به داخل.","دمبل را به‌آرامی به پهلو پایین ببرید و آرنج را کمی خم نگه دارید.","وقتی بازو موازی زمین شد لحظه‌ای مکث کنید.","با انقباض عضلات سینه، دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0353":{"name":"جلوبازو تمرکزی تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","دمبل را در یک دست با کف رو به بالا بگیرید؛ بازو به سمت زمین دراز.","آرنج را روی داخل ران، کمی بالای زانو تکیه دهید.","بازو ثابت بماند و همزمان با انقباض جلوبازو و بازدم، دمبل به سمت شانه بالا کشیده شود.","در بالای حرکت مکث کنید، سپس نفس بگیرید و دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کرده و دوباره تکرار کنید."]},
"1287":{"name":"پرس سینه زیرسینه تک‌دست دمبل","steps":["روی میز زیرسینه دراز بکشید و یک دمبل در یک دست بگیرید؛ روی سینه بگذارید.","کف پاها صاف روی زمین و کمر محکم به میز چسبیده باشد.","بازو را دراز کنید و دمبل را تا صاف‌شدن کامل آرنج به سمت سقف پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1288":{"name":"قفسه سینه تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، یک دمبل در یک دست و کف پاها صاف روی زمین.","پاها را به جلو حرکت دهید و بدن را پایین غلتانید تا پشت بالایی روی توپ ورزشی باشد.","بازو را با دمبل صاف بالای سینه دراز کنید؛ کف دست رو به داخل.","دمبل را به‌آرامی به پهلو پایین ببرید و آرنج را کمی خم نگه دارید.","لحظه‌ای مکث کنید، سپس با انقباض عضلات سینه دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1736":{"name":"پرس فرانسوی تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","دمبل را در یک دست با کف رو به بالا بگیرید؛ آرنج با زاویه ۹۰ درجه خم.","بازو را با آرنج ثابت به سمت سقف دراز کنید.","دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1663":{"name":"جلوبازو چکشی لاری تک‌دست دمبل","steps":["روی میز لاری با دمبل در یک دست بنشینید؛ بازو روی پد.","دمبل را با گریپ خنثی بگیرید (کف دست رو به بدن).","بازو را ثابت نگه دارید، بازدم کنید و دمبل را به سمت شانه بالا بکشید.","در بالای حرکت مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1621":{"name":"پرس چکشی تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","دمبل را در یک دست با کف رو به داخل بگیرید؛ آرنج با زاویه ۹۰ درجه خم.","برای تثبیت، دست دیگر را روی لگن بگذارید.","دمبل را با دراز‌کردن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1289":{"name":"پرس سینه بالاسینه تک‌دست دمبل","steps":["میز بالاسینه را روی زاویه ۴۵ درجه تنظیم کنید.","روی میز بنشینید؛ کمر به پد چسبیده و کف پاها صاف روی زمین.","دمبل را در یک دست با دست از پشت بگیرید و روی شانه بگذارید.","دمبل را از بدن دور و با دراز‌کردن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0354":{"name":"کیک‌بک تک‌دست دمبل","steps":["با پاهای به عرض شانه بایستید و دمبل را در دست راست بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","آرنج راست را به پهلو بالا بیاورید؛ با زاویه ۹۰ درجه خم بماند.","بازوی راست را صاف به عقب دراز کنید و در بالای حرکت پشت‌بازو را منقبض کنید.","دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0355":{"name":"نشر جانب تک‌دست دمبل","steps":["بایستید، پاها به عرض شانه و یک دمبل در یک دست بگیرید؛ کف دست رو به بدن.","در طول حرکت کمر را صاف و میان‌تنه را منقبض نگه دارید.","دمبل را با بازوی صاف و کف رو به پایین به پهلو بالا ببرید.","بلندکردن را ادامه دهید تا بازو موازی زمین شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0356":{"name":"نشر جانب تک‌دست با تکیه‌گاه دمبل","steps":["با پاهای به عرض شانه بایستید و دمبل را در یک دست با کف رو به بدن بگیرید.","دست دیگر را برای تکیه روی سطح ثابتی مثل میز یا دیوار بگذارید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دمبل را با بازوی صاف و کف رو به پایین به پهلو بالا ببرید.","بلندکردن را ادامه دهید تا بازو موازی زمین شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"1290":{"name":"پرس سینه تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","دمبل را در یک دست هم‌سطح شانه نگه دارید؛ آرنج خم و کف دست رو به جلو.","میان‌تنه منقبض و تعادل روی توپ حفظ شود؛ دمبل به‌آرامی تا صاف‌شدن کامل بازو پرس شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1665":{"name":"جلوبازو رو به زمین تک‌دست دمبل","steps":["رو به زمین روی میز صاف دراز بکشید و دمبل را در یک دست با کف رو به پایین بگیرید.","بازو را کاملاً دراز کنید و اجازه دهید صاف به سمت زمین آویزان باشد.","بازو ثابت بماند و دمبل با انقباض جلوبازو به سمت شانه بالا کشیده شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1666":{"name":"جلوبازو چکشی رو به زمین تک‌دست دمبل","steps":["رو به زمین روی میز صاف دراز بکشید؛ دمبل در یک دست با کف رو به بدن و بازو کاملاً دراز.","بازو ثابت بماند و دمبل با انقباض جلوبازو به سمت شانه کشیده شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1291":{"name":"پول‌اور تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","دمبل را با یک دست بگیرید و بازو را صاف بالای سینه دراز کنید.","دمبل را با بازوی صاف به‌آرامی پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0358":{"name":"مچ دست برعکس تک‌دست دمبل","steps":["روی میز یا صندلی بنشینید و کف پاها صاف روی زمین باشد.","دمبل را در یک دست با دست از پشت و کف رو به پایین بگیرید.","ساعد را روی ران بگذارید و مچ از لبه آویزان باشد.","دمبل را با خم‌کردن مچ به سمت زمین پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس مچ را به‌آرامی به سمت بدن بالا بکشید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0359":{"name":"نشر برعکس تک‌دست با تکیه‌گاه دمبل","steps":["روی میز با کف پاها صاف روی زمین و کمر صاف بنشینید.","دمبل را در یک دست با کف رو به داخل بگیرید.","به جلو خم شوید و دست آزاد را برای تکیه روی میز بگذارید.","بازو را کمی خم نگه دارید و به پهلو بالا ببرید تا موازی زمین شود.","در بالای حرکت مکث کنید، سپس بازو را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1622":{"name":"پرس سینه با گریپ برعکس تک‌دست دمبل","steps":["روی میز صاف با دمبل در یک دست بنشینید؛ کف دست رو به بدن.","کف پاها صاف روی زمین و کمر صاف باشد.","دمبل را با آرنج نزدیک بدن هم‌سطح شانه بالا ببرید.","دمبل را تا صاف‌شدن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1414":{"name":"جلوبازو لاری برعکس تک‌دست دمبل","steps":["روی میز لاری با سینه چسبیده به پد بنشینید؛ بازو روی لبه میز دراز و دمبل با دست از جلو.","دمبل را به‌آرامی پایین ببرید تا بازو کاملاً صاف شود.","دمبل را با بازوی ثابت به سمت شانه برگردانید.","در بالای حرکت جلوبازو را منقبض کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1667":{"name":"جلوبازو اسپایدر برعکس تک‌دست دمبل","steps":["صاف بایستید؛ دمبل در یک دست، کف رو به پایین و بازو کاملاً صاف.","بازو ثابت بماند و دمبل با خم‌کردن آرنج به سمت شانه کشیده شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1668":{"name":"جلوبازو نشسته تک‌دست روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","دمبل را در یک دست با کف رو به بالا بگیرید؛ بازو کاملاً دراز.","بازو ثابت بماند و دمبل با انقباض جلوبازو به سمت شانه کشیده شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1669":{"name":"جلوبازو چکشی نشسته تک‌دست دمبل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","دمبل را در یک دست با گریپ خنثی بگیرید (کف دست رو به داخل).","آرنج را روی داخل ران، کمی بالای زانو تکیه دهید.","بازو را ثابت نگه دارید، بازدم کنید و دمبل را به سمت شانه بالا بکشید.","در بالای حرکت مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1415":{"name":"مچ دست خنثی نشسته تک‌دست دمبل","steps":["روی میز با کف پاها صاف روی زمین بنشینید و دمبل را در یک دست با کف رو به بالا بگیرید.","ساعد را روی ران بگذارید و اجازه دهید مچ از لبه آویزان باشد.","ساعد ثابت بماند و مچ تا حد ممکن به بالا خم شود.","در بالا مکث کنید، سپس مچ را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0361":{"name":"پرس سرشانه تک‌دست دمبل","steps":["بایستید، پاها به عرض شانه و دمبل را در یک دست هم‌سطح شانه بگیرید؛ کف رو به جلو.","دمبل را تا صاف‌شدن کامل بازو به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0360":{"name":"پرس سرشانه تک‌دست دمبل نسخه ۲","steps":["بایستید، پاها به عرض شانه و دمبل را در یک دست هم‌سطح شانه بگیرید؛ کف رو به جلو.","میان‌تنه را منقبض کنید و دمبل را صاف از بالای سر پرس کنید؛ بازو کاملاً صاف.","در بالا مکث کنید، سپس دمبل را به‌آرامی هم‌سطح شانه برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"3888":{"name":"اسنچ تک‌دست دمبل","steps":["بایستید، پاها به عرض شانه و یک دمبل را با دست از پشت در یک دست بگیرید.","زانوها را کمی خم کنید و از لگن به جلو خم شوید؛ کمر صاف و سینه بالا.","دمبل را نزدیک بدن به سمت زمین پایین ببرید.","لگن، زانوها و مچ پا را با قدرت صاف کنید تا دمبل در خطی صاف به بالا برود.","وقتی دمبل هم‌سطح شانه رسید، سریع دست را بچرخانید و با بازوی کاملاً صاف آن را از بالای سر به جلو پرتاب کنید.","دمبل را بالای سر با کمی خم در زانوها و لگن بگیرید.","دمبل را با کنترل به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1670":{"name":"جلوبازو ایستاده تک‌دست دمبل","steps":["صاف بایستید؛ دمبل در یک دست، کف رو به جلو و بازو کاملاً صاف.","بازو ثابت بماند و همزمان با انقباض جلوبازو و بازدم، وزنه به بالا کشیده شود.","دمبل را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1671":{"name":"جلوبازو چکشی ایستاده تک‌دست دمبل","steps":["صاف بایستید و در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به تنه باشد.","آرنج‌ها را نزدیک تنه و بازوها را ثابت نگه دارید.","بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0362":{"name":"پشت‌بازو تک‌دست روی میز دمبل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","دمبل را در یک دست بگیرید و دست دیگر را برای تکیه روی میز بگذارید.","دمبل را با بازوی نزدیک سر و آرنج رو به جلو بالای سر ببرید.","دمبل را با خم‌کردن آرنج و بازوی ثابت پشت سر پایین ببرید.","بازو را با صاف‌کردن کامل آرنج به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"0363":{"name":"زیربغل قائم تک‌دست دمبل","steps":["بایستید، پاها به عرض شانه و یک دمبل را با دست از پشت در یک دست بگیرید.","اجازه دهید دمبل با فاصله یک بازو جلوی ران‌ها و کف دست رو به بدن آویزان باشد.","با کمر صاف و میان‌تنه منقبض، بازدم کنید و دمبل را با پیشتازی آرنج صاف به سمت چانه بالا ببرید.","در بالا مکث کنید، سپس نفس بگیرید و دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0364":{"name":"مچ دست تک‌دست دمبل","steps":["روی میز یا صندلی بنشینید و کف پاها صاف روی زمین باشد.","دمبل را در یک دست با دست از جلو بگیرید و ساعد را روی ران بگذارید.","مچ را باز کنید و اجازه دهید دمبل به سمت انگشتان پایین بلغزد.","مچ را به‌آرامی به بالا برگردانید و دمبل را به سمت ساعد بیاورید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"1672":{"name":"جلوبازو زوتمن لاری تک‌دست دمبل","steps":["روی میز لاری بنشینید و دمبل را در یک دست با دست از جلو بگیرید.","بازو را روی پد میز لاری بگذارید و اجازه دهید بازو کاملاً صاف شود.","دمبل را با بازوی ثابت به سمت شانه بالا بکشید.","در بالای جلوبازو، مچ را بچرخانید تا کف دست رو به بالا شود.","دمبل را به‌آرامی به موقعیت شروع برگردانید و مچ را به حالت اولیه بچرخانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1292":{"name":"قفسه سینه تک‌پا روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","یک پا را روی زمین بگذارید و پای دیگر را صاف جلوی خود دراز کنید.","کمی به جلو خم شوید و بازوها را با کمی خم در آرنج به طرفین ببرید.","دمبل‌ها را پایین و به طرفین ببرید تا کشش سینه را احساس کنید.","در پایین‌ترین نقطه مکث کنید، سپس با انقباض عضلات سینه دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس پاها را عوض کنید و دوباره تکرار کنید."]},
"0365":{"name":"مچ دست خنثی روی میز دمبل","steps":["روی میز با کف پاها صاف روی زمین بنشینید و در هر دست دمبل با کف رو به بالا بگیرید.","ساعدها را روی میز بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.","بازوها ثابت بمانند و همزمان با بازدم، دمبل‌ها به سمت شانه‌ها بالا کشیده شوند.","در بالای حرکت مکث کنید، سپس نفس بگیرید و دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0366":{"name":"مچ دست خنثی تک‌دست روی میز دمبل","steps":["روی میز با دمبل در یک دست بنشینید؛ بازو روی میز دراز و کف دست رو به بالا.","بازو ثابت بماند و دمبل با مچ خنثی به سمت شانه کشیده شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1441":{"name":"مچ دست برعکس تک‌دست روی میز دمبل","steps":["روی میز با کف پاها صاف روی زمین بنشینید و دمبل را در یک دست با کف رو به پایین بگیرید.","ساعد را روی میز بگذارید و مچ از لبه آویزان باشد.","مچ را به‌آرامی به بالا بچرخانید و دمبل را به سمت ساعد بیاورید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0367":{"name":"مچ دست تک‌دست روی میز دمبل","steps":["روی میز با کف پاها صاف روی زمین بنشینید و دمبل را در یک دست با کف رو به پایین بگیرید.","ساعد را روی میز بگذارید و مچ از لبه آویزان باشد.","مچ را به‌آرامی به بالا بچرخانید و دمبل را به سمت ساعد بیاورید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0368":{"name":"مچ دست برعکس روی میز دمبل","steps":["روی میز با کف پاها صاف روی زمین بنشینید و در هر دست دمبل با کف رو به پایین بگیرید.","ساعدها را روی میز بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.","مچ‌ها را به‌آرامی به بالا بچرخانید و دمبل‌ها را به سمت بدن بیاورید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0369":{"name":"مچ دست روی میز دمبل","steps":["روی میز بنشینید؛ ساعدها روی میز، کف دست‌ها رو به بالا و در هر دست دمبل.","اجازه دهید مچ‌ها از لبه میز آویزان باشند.","مچ‌ها را به‌آرامی به بالا خم کنید؛ در بالای حرکت ساعدها منقبض شوند.","لحظه‌ای مکث کنید، سپس مچ‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1329":{"name":"زیربغل خم چرخشی کف دست دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل را با دست از پشت بگیرید.","از لگن به جلو خم شوید؛ کمر صاف و زانوها کمی خم.","اجازه دهید بازوها با کف دست‌ها رو به بدن صاف آویزان باشند.","میان‌تنه را منقبض کنید و دمبل‌ها را با آرنج‌های نزدیک بدن به سمت سینه بکشید.","همزمان با بالاکشیدن دمبل‌ها، کف دست‌ها را بچرخانید تا رو به بیرون از بدن شوند.","در بالای حرکت کتف‌ها را به هم فشار دهید.","دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید و کف دست‌ها را به حالت اولیه بچرخانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1623":{"name":"پرس بالاسینه با کف رو به داخل دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی میز با کمر چسبیده به پشتی و کف پاها صاف روی زمین بنشینید.","در هر دست دمبل را با دست از پشت و کف رو به داخل بگیرید.","بازوها را با کمی خم در آرنج‌ها صاف بالای سینه دراز کنید.","دمبل‌ها را با آرنج‌های نزدیک بدن به‌آرامی به سمت شانه‌ها پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس دمبل‌ها را به موقعیت شروع پرس کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0370":{"name":"جلوبازو چکشی لاری دمبل","steps":["صاف بایستید و در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به تنه باشد.","آرنج‌ها را نزدیک تنه نگه دارید و کف دست‌ها را بچرخانید تا رو به جلو شوند.","این موقعیت شروع شماست.","اکنون با ثابت‌نگه‌داشتن بازوها، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","سپس نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","تعداد تکرار توصیه‌شده را انجام دهید."]},
"0371":{"name":"اسکوات پلایومتریک دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل کنار بدن.","با خم‌کردن زانوها و عقب‌بردن لگن، بدن را به حالت اسکوات پایین ببرید.","در پایین‌ترین نقطه اسکوات، با انفجار به بالا بپرید و از زمین جدا شوید.","در هوا، سریع جای پاها را عوض کنید و با پای مخالف جلو فرود بیایید.","فوراً بدن را به حالت اسکوات پایین ببرید و پرش را با جابه‌جایی دوباره پاها تکرار کنید.","جای پاها را در هر پرش برای تعداد دلخواه تکرار عوض کنید."]},
"0372":{"name":"جلوبازو لاری دمبل","steps":["روی میز لاری بنشینید؛ بازوها روی پد و سینه چسبیده به آن.","در هر دست یک دمبل بگیرید؛ کف دست‌ها رو به بالا و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1673":{"name":"جلوبازو لاری روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","دمبل را در یک دست با دست از جلو بگیرید و آرنج را روی توپ سوئیسی بگذارید.","بازو را ثابت نگه دارید، بازدم کنید و دمبل را به سمت شانه بالا بکشید.","در بالا مکث کنید، سپس نفس بگیرید و دمبل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1293":{"name":"پرس سینه روی توپ سوئیسی دمبل","steps":["روی توپ ورزشی با کف پاها صاف روی زمین بنشینید؛ دمبل‌ها روی ران‌ها.","پاها را به‌آرامی به جلو حرکت دهید و توپ را غلتانید تا کمر پایین روی توپ و زانوها ۹۰ درجه باشد.","دمبل‌ها را هم‌سطح شانه با کف دست‌ها رو به جلو بالا ببرید.","دمبل‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0373":{"name":"پشت‌بازو با گریپ رو به پایین دمبل","steps":["روی میز یا صندلی با کمر صاف و کف پاها صاف روی زمین بنشینید.","دمبل را با هر دو دست و کف رو به پایین بگیرید و بازوها را صاف بالای سر دراز کنید.","بازوها نزدیک سر و آرنج‌ها رو به جلو؛ دمبل با خم‌کردن آرنج‌ها به‌آرامی پشت سر پایین برود.","لحظه‌ای مکث کنید، سپس بازوها را صاف کرده و به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0374":{"name":"جلوبازو بالاسینه رو به زمین دمبل","steps":["میز را روی زاویه بالاسینه ۴۵ درجه تنظیم کنید.","رو به زمین روی میز دراز بکشید؛ سینه و شکم روی میز.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به پایین و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1674":{"name":"جلوبازو چکشی بالاسینه رو به زمین دمبل","steps":["میز را روی زاویه بالاسینه ۴۵ درجه تنظیم کنید.","رو به زمین روی میز دراز بکشید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به هم.","بگذارید بازوها با کمی خم در آرنج صاف به سمت زمین آویزان باشند.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0375":{"name":"پول‌اور دمبل","steps":["روی میز دراز بکشید؛ سر در یک انتهای میز و پاها روی زمین.","دمبل را با هر دو دست بگیرید و بازوها را صاف بالای سینه دراز کنید.","با کمی خم در آرنج‌ها، دمبل را به‌آرامی پشت سر پایین ببرید تا کشش سینه و سرشانه‌ها را احساس کنید.","لحظه‌ای مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1294":{"name":"پول‌اور با اکستنشن ران روی توپ سوئیسی دمبل","steps":["روی توپ ورزشی با کف پاها صاف روی زمین بنشینید؛ دمبل روی ران‌ها.","پاها را به‌آرامی به جلو حرکت دهید و توپ را روی کمر پایین بیاورید تا سر، گردن و پشت بالایی روی توپ تکیه کنند.","دمبل را با هر دو دست بگیرید و بازوها را با کمی خم در آرنج صاف روی سینه دراز کنید.","دمبل را با بازوهای صاف و با کنترل پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","با بازوهای دراز، لگن را با انقباض باسن و میان‌تنه از زمین بلند کنید.","لگن را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1295":{"name":"پول‌اور روی توپ سوئیسی دمبل","steps":["روی توپ ورزشی بنشینید و دمبل را با هر دو دست بالای سینه و بازوهای دراز نگه دارید.","دمبل را با بازوهای صاف به‌آرامی پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1700":{"name":"پرس پوش دمبل","steps":["با پاهای به عرض شانه بایستید؛ دمبل در هر دست هم‌سطح شانه.","زانوها را کمی خم کنید و بدن را پایین ببرید، سپس با صاف‌کردن انفجاری پاها دمبل‌ها را از بالای سر پرس کنید.","در بالای حرکت بازوها را قفل کنید، سپس دمبل‌ها را تا هم‌سطح شانه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0376":{"name":"نشر دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2292":{"name":"نشر خلفی دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0377":{"name":"زیربغل نشر خلفی سرشانه دمبل","steps":["بایستید، پاها به عرض شانه و زانوها کمی خم باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","از کمر به جلو خم شوید و کمر را صاف و میان‌تنه را منقبض نگه دارید.","بازوها را با کمی خم در آرنج‌ها صاف به سمت زمین دراز کنید.","دمبل‌ها را به طرفین بالا ببرید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0378":{"name":"قفسه خلفی دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","بازوها را صاف به سمت زمین دراز کنید؛ کف دست‌ها رو به هم.","با کمی خم در آرنج‌ها، بازوها را به طرفین بالا ببرید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0380":{"name":"نشر خلفی دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن.","زانوها را کمی خم کنید و از لگن به جلو خم شوید؛ کمر صاف و میان‌تنه منقبض.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0379":{"name":"نشر خلفی با تکیه سر دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0381":{"name":"لانژ از عقب دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","با پای راست به عقب قدم بردارید و بدن را به حالت لانژ پایین ببرید.","زانوی چپ را خم کنید و بدن را پایین ببرید تا ران چپ موازی زمین شود.","لحظه‌ای مکث کنید، سپس با فشار پاشنه چپ به موقعیت شروع برگردید.","در طرف دیگر با قدم‌گذاشتن پای چپ به عقب تکرار کنید."]},
"0382":{"name":"جلوبازو با گریپ برعکس دمبل","steps":["صاف بایستید و در هر دست دمبل بگیرید؛ کف رو به پایین و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","وزنه‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1624":{"name":"پرس سینه برعکس دمبل","steps":["روی میز دراز بکشید؛ کف پاها صاف روی زمین و زانوها خم.","در هر دست دمبل را با دست از پشت و کف رو به پاها بگیرید.","بازوها را با کمی خم در آرنج‌ها صاف به سمت سقف دراز کنید.","دمبل‌ها را به‌آرامی به سمت سینه پایین ببرید و اجازه دهید آرنج‌ها به طرفین باز شوند.","در پایین‌ترین نقطه مکث کنید، سپس دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0383":{"name":"نشر برعکس دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست یک دمبل بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","بازوها را صاف جلوی خود به پایین دراز کنید؛ کف دست‌ها رو به هم.","با کمی خم در آرنج‌ها، بازوها را به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1330":{"name":"زیربغل بالاسینه با گریپ برعکس تک‌دست دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","دمبل را کنار میز روی زمین بگذارید.","روبه‌روی میز با پاهای به عرض شانه بایستید.","از کمر خم شوید و زانوی چپ و دست چپ را برای تکیه روی میز بگذارید.","دمبل را با دست راست و گریپ برعکس بردارید (کف دست رو به پایین).","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دمبل را با آرنج نزدیک بدن به سمت سینه بکشید.","در بالای حرکت عضلات پشت را منقبض کنید.","دمبل را با کنترل به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید.","طرف را عوض کنید و حرکت را با دست چپ تکرار کنید."]},
"1331":{"name":"زیربغل بالاسینه با گریپ برعکس دو دست دمبل","steps":["میز بالاسینه را با زاویه ۴۵ درجه تنظیم کنید.","روی میز با سینه چسبیده به پشتی و کف پاها صاف روی زمین بنشینید.","در هر دست دمبل را با دست از جلو بگیرید.","به جلو خم شوید و اجازه دهید بازوها کاملاً صاف رو به پایین آویزان باشند.","دمبل‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2327":{"name":"زیربغل با گریپ برعکس دمبل (زن)","steps":["بایستید، پاها به عرض شانه و زانوها کمی خم باشد.","در هر دست دمبل را با دست از پشت و کف رو به بدن بگیرید.","از کمر به جلو خم شوید و کمر را صاف و میان‌تنه را منقبض نگه دارید.","اجازه دهید بازوها با کمی خم در آرنج صاف رو به پایین آویزان باشند.","دمبل‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0384":{"name":"جلوبازو لاری برعکس دمبل","steps":["روی میز لاری بنشینید؛ بازوها روی پد و سینه چسبیده به تکیه‌گاه.","در هر دست دمبل را با دست از جلو و کف رو به بالا بگیرید.","بازوها ثابت بمانند و همزمان با انقباض جلوبازو و بازدم، دمبل‌ها بالا کشیده شوند.","جلوبازو را ادامه دهید تا جلوبازوها کاملاً منقبض و دمبل‌ها هم‌سطح شانه شوند.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1675":{"name":"جلوبازو اسپایدر برعکس دمبل","steps":["صاف بایستید؛ دمبل در هر دست، کف رو به بدن و بازوها کاملاً صاف.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","دمبل‌ها را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0385":{"name":"مچ دست برعکس دمبل","steps":["روی میز یا صندلی بنشینید و کف پاها صاف روی زمین باشد.","در هر دست دمبل را با دست از پشت و کف رو به پایین بگیرید.","ساعدها را روی ران‌ها بگذارید و اجازه دهید مچ‌ها از لبه آویزان باشند.","مچ‌ها را به‌آرامی به بالا بچرخانید و دمبل‌ها را به سمت بدن بیاورید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1459":{"name":"ددلیفت رومانیایی دمبل","steps":["بایستید، پاها به عرض شانه و در هر دست دمبل را با دست از پشت بگیرید.","با کمر صاف و میان‌تنه منقبض، از لگن خم شوید و دمبل‌ها را به سمت زمین پایین ببرید؛ زانوها کمی خم شوند.","دمبل‌ها را پایین ببرید تا کشش پشت پا را احساس کنید، سپس با فشار پاشنه‌ها و انقباض باسن به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0386":{"name":"نشر برعکس چرخشی دمبل","steps":["با پاهای به عرض شانه بایستید و در هر دست دمبل با کف رو به داخل بگیرید.","زانوها را کمی خم کنید و از لگن به جلو خم شوید؛ کمر صاف و سینه بالا.","بازوها را با کمی خم در آرنج به طرفین بالا ببرید تا موازی زمین شوند.","بازوها را بچرخانید تا کف دست‌ها رو به پایین شوند.","بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2397":{"name":"پرس اسکات دمبل","steps":["روی میز بنشینید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","دمبل‌ها را هم‌سطح شانه بالا ببرید؛ آرنج‌ها خم و کف دست‌ها رو به جلو.","دمبل‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0387":{"name":"نشر از جلو نشسته یک‌درمیان دمبل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن و بازوها کنار بدن دراز.","با بازوهای صاف، یک دمبل را جلوی خود بالا ببرید تا موازی زمین شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس دمبل را به‌آرامی به موقعیت شروع برگردانید.","حرکت را با دست دیگر تکرار کنید.","برای تعداد دلخواه تکرار، بین دست‌ها جابه‌جا شوید."]},
"1676":{"name":"جلوبازو چکشی نشسته یک‌درمیان روی توپ سوئیسی دمبل","steps":["روی توپ سوئیسی بنشینید، کف پاها صاف روی زمین و کمر صاف باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن و بازوها کاملاً صاف.","بازوها ثابت بمانند و همزمان با بازدم، یک دمبل با کف دست رو به بدن به سمت شانه بالا کشیده شود.","دمبل را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی دمبل را به موقعیت شروع برگردانید.","حرکت را با بازوی مخالف تکرار کنید.","به‌تناوب دست‌ها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"0388":{"name":"پرس نشسته یک‌درمیان دمبل","steps":["روی میز بنشینید و در هر دست دمبل بگیرید؛ کف دست‌ها رو به جلو.","دمبل‌ها را هم‌سطح شانه بالا ببرید؛ آرنج‌ها خم و کف دست‌ها رو به جلو.","یک دمبل را با بازوی کاملاً صاف از بالای سر پرس کنید.","دمبل را هم‌سطح شانه پایین برگردانید.","حرکت را با دست دیگر تکرار کنید.","به‌تناوب دست‌ها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"3546":{"name":"پرس سرشانه نشسته یک‌درمیان دمبل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به داخل و هم‌سطح شانه بالا ببرید.","یک دمبل را از بالای سر پرس کنید و دمبل دیگر هم‌سطح شانه بماند.","دمبلِ بالابرده‌شده را هم‌سطح شانه پایین بیاورید و همزمان دمبل دیگر را از بالای سر پرس کنید.","برای تعداد دلخواه تکرار، بین دست‌ها یک‌درمیان ادامه دهید."]},
"0389":{"name":"پشت‌بازو نشسته روی میز دمبل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","دمبل را با هر دو دست بگیرید و بازوها را صاف بالای سر دراز کنید.","دمبل را با آرنج‌های نزدیک گوش به‌آرامی پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس دمبل را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2317":{"name":"نشر جانب با بازوی خم نشسته دمبل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","در هر دست دمبل بگیرید؛ کف دست‌ها رو به بدن و بازوها با زاویه ۹۰ درجه خم.","با آرنج‌های خم، بازوها را به طرفین بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]}
});

