window.FA_EX=window.FA_EX||{};Object.assign(window.FA_EX,{
"0530":{"name":"آسیاب بادی دوتایی کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را در دست راست بگیرید.","بازوی راست را بالای سر دراز کنید و نگاه به کتل‌بل باشد.","پای چپ را ۴۵ درجه به چپ و پای راست را ۹۰ درجه به راست بچرخانید.","به سمت چپ از کمر خم شوید و بازوی راست بالای سر صاف بماند.","کتل‌بل را به سمت پای چپ پایین ببرید.","لحظه‌ای مکث کنید، سپس با انقباض میان‌تنه و فشار پای راست به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0531":{"name":"پرس تک‌دست دامنه بلند روی زمین کتل‌بل","steps":["به پشت روی زمین دراز بکشید؛ زانوها خم و کف پاها صاف روی زمین.","کتل‌بل را در یک دست بگیرید؛ کف دست رو به پاها.","بازو را با آرنج قفل‌شده و مچ صاف به سمت سقف دراز کنید.","کتل‌بل را با کنترل کامل در طول حرکت به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0532":{"name":"شکل ۸ کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را در یک دست بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","کتل‌بل را بین پاها عبور دهید و وقتی به پشت پاها رسید دست را عوض کنید.","وقتی کتل‌بل به جلو آمد، آن را بین پاها به دست دیگر بدهید.","عبور کتل‌بل بین پاها را به‌صورت حرکت شکل ۸ ادامه دهید.","در طول حرکت سرعت ثابت و میان‌تنه منقبض باشد.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0533":{"name":"اسکوات از جلو کتل‌بل","steps":["بایستید، پاها به عرض شانه و پنجه‌ها کمی رو به بیرون باشد.","کتل‌بل را با هر دو دست جلوی سینه و نزدیک بدن بگیرید.","میان‌تنه را منقبض و سینه را بالا نگه دارید؛ لگن را مثل نشستن روی صندلی به پایین و عقب ببرید.","تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.","با فشار پاشنه‌ها بلند شوید و در بالا باسن را منقبض کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0534":{"name":"گابلِت اسکوات کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را با هر دو دست نزدیک سینه بگیرید.","با سینه بالا و میان‌تنه منقبض، با خم‌کردن زانوها و لگن بدن را به حالت اسکوات پایین ببرید.","به پایین‌کردن ادامه دهید تا ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.","در پایین‌ترین نقطه مکث کنید، سپس با فشار پاشنه‌ها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0535":{"name":"کلین از حالت آویزان کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را جلوی ران‌ها بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","کتل‌بل را به سمت زمین پایین ببرید و اجازه دهید بین پاها تاب بخورد.","لگن و زانوها را سریع صاف کنید و با شتاب حاصل کتل‌بل را هم‌سطح شانه تاب دهید.","وقتی کتل‌بل هم‌سطح شانه رسید، مچ‌ها را بچرخانید و آن را در حالت رک بگیرید؛ آرنج نزدیک بدن و کتل‌بل روی ساعد.","کتل‌بل را بین پاها به موقعیت شروع برگردانید و برای تعداد دلخواه تکرار کنید."]},
"0536":{"name":"لانژ با عبور کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را با هر دو دست جلوی سینه بگیرید.","با پای راست یک قدم به جلو بردارید و بدن را به حالت لانژ پایین ببرید.","همزمان با لانژ رو به جلو، کتل‌بل را زیر ران راست عبور دهید و به دست چپ بدهید.","با هُل پای راست به موقعیت شروع برگردید و همزمان کتل‌بل را به دست راست برگردانید.","لانژ را در طرف مخالف با عبور کتل‌بل زیر ران چپ تکرار کنید.","لانژها را با عبور کتل‌بل بین دست‌ها یک‌درمیان برای تعداد دلخواه ادامه دهید."]},
"0537":{"name":"کلین و جرک تک‌دست کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را با دست از پشت در یک دست بگیرید.","زانوها را کمی خم کنید و از لگن خم شوید تا کتل‌بل بین پاها پایین برود.","لگن، زانوها و مچ پا را با قدرت صاف کنید و با شتاب حاصل، کتل‌بل را هم‌سطح شانه تاب دهید.","وقتی کتل‌بل هم‌سطح شانه رسید، مچ را بچرخانید و دست را صاف به بالا ببرید؛ بازو در بالای سر قفل شود.","کتل‌بل را به موقعیت شروع برگردانید و برای تعداد دلخواه تکرار کنید."]},
"1298":{"name":"پرس زمین تک‌دست کتل‌بل","steps":["روی زمین به پشت دراز بکشید؛ زانوها خم و کف پاها صاف روی زمین.","کتل‌بل را در یک دست با کف رو به پاها بگیرید و بازو را صاف به سمت سقف دراز کنید.","کتل‌بل را با خم‌کردن آرنج و بازوی نزدیک بدن به‌آرامی به سمت سینه پایین ببرید.","وقتی کتل‌بل کمی بالای سینه بود مکث کنید، سپس با صاف‌کردن آرنج آن را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0538":{"name":"جرک تک‌دست کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را در یک دست هم‌سطح شانه نگه دارید.","زانوها را کمی خم کنید و عضلات میان‌تنه را منقبض کنید.","کتل‌بل را در خطی صاف با بازوی کاملاً صاف از بالای سر پرس کنید.","همزمان با پرس کتل‌بل از بالای سر، زانوها را کمی خم و سریع صاف کنید تا شتاب بگیرید.","وقتی کتل‌بل به بالاترین نقطه رسید، با خم‌کردن زانوها و لگن سریع زیر آن بروید.","کتل‌بل را با کمی خم در زانوها و لگن بگیرید؛ بازو کاملاً صاف بالای سر.","صاف بایستید؛ زانوها و لگن کاملاً صاف و کتل‌بل پایدار بالای سر.","کتل‌بل را با خم‌کردن زانوها و لگن به موقعیت شروع برگردانید و برای تعداد دلخواه تکرار کنید."]},
"0539":{"name":"پرس نظامی از پهلو تک‌دست کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را در یک دست هم‌سطح شانه نگه دارید.","میان‌تنه را منقبض و کمر را صاف نگه دارید.","کتل‌بل را با دراز‌کردن کامل بازو از بالای سر پرس کنید.","در بالا مکث کنید، سپس کتل‌بل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0540":{"name":"پرس پوش تک‌دست کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را در یک دست هم‌سطح شانه بگیرید.","زانوها را کمی خم کنید و عضلات میان‌تنه را منقبض کنید.","کتل‌بل را با دراز‌کردن بازو و صاف‌کردن کامل پاها از بالای سر پرس کنید.","کتل‌بل را با خم‌کردن زانو و برگرداندن آن به شانه به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0541":{"name":"زیربغل تک‌دست کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را با دست از پشت در یک دست بگیرید.","زانوها را کمی خم کنید و از لگن به جلو خم شوید؛ کمر صاف و میان‌تنه منقبض.","کتل‌بل را با آرنج نزدیک بدن و فشار کتف‌ها به سمت سینه بالا بکشید.","در بالا مکث کنید، سپس کتل‌بل را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کرده و با دست دیگر تکرار کنید."]},
"0542":{"name":"اسنچ تک‌دست کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را در یک دست بین پاها بگیرید.","زانوها را کمی خم کنید و از لگن خم شوید تا کتل‌بل به سمت زمین پایین برود.","لگن و زانوها را با قدرت صاف کنید و با شتاب حاصل، کتل‌بل را به سمت شانه تاب دهید.","وقتی کتل‌بل هم‌سطح شانه رسید، دست را بچرخانید و با بازوی کاملاً صاف آن را صاف از بالای سر بالا ببرید.","کتل‌بل را بین پاها پایین برگردانید و برای تعداد دلخواه تکرار کنید."]},
"0543":{"name":"پارالل پای دزد دریایی کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را در یک دست بگیرید.","زانوها را کمی خم کنید و با کمر صاف از لگن به جلو خم شوید.","کتل‌بل را با آرنج نزدیک بدن هم‌سطح شانه بالا ببرید.","بازو را با صاف‌کردن آرنج کاملاً بالای سر دراز کنید.","کتل‌بل را هم‌سطح شانه پایین برگردانید، سپس به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0544":{"name":"اسکوات تک‌پا (پیستول) کتل‌بل","steps":["بایستید، پاها به عرض شانه و کتل‌بل را با هر دو دست جلوی سینه بگیرید.","پای چپ را از زمین بلند کنید و صاف جلو دراز کنید؛ موازی زمین.","بدن را به‌آرامی به حالت اسکوات پایین ببرید؛ کف پای راست صاف روی زمین و پای چپ دراز.","در پایین‌ترین نقطه اسکوات مکث کنید، سپس با فشار پاشنه راست به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس پا را عوض کنید."]},
"0545":{"name":"شنا سوئدی پلایومتریک کتل‌بل","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها روی کتل‌بل‌ها به عرض شانه.","سینه را با آرنج‌های نزدیک بدن به سمت زمین پایین ببرید.","دست‌ها را با فشار انفجاری از روی کتل‌بل‌ها بلند کنید و بازوها را کاملاً دراز کنید.","نرم روی کتل‌بل‌ها فرود بیایید و فوراً برای تکرار بعدی سینه را پایین ببرید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0546":{"name":"پرس نشسته کتل‌بل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","در هر دست یک کتل‌بل هم‌سطح شانه بگیرید؛ کف دست‌ها رو به جلو.","کتل‌بل‌ها را با بازوهای کاملاً صاف از بالای سر پرس کنید.","کتل‌بل‌ها را هم‌سطح شانه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1438":{"name":"پرس نظامی دو دست نشسته کتل‌بل","steps":["روی میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","در هر دست یک کتل‌بل هم‌سطح شانه بگیرید؛ کف دست‌ها رو به جلو.","کتل‌بل‌ها را با دراز‌کردن کامل بازوها از بالای سر پرس کنید.","در بالا مکث کنید، سپس کتل‌بل‌ها را به‌آرامی هم‌سطح شانه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0547":{"name":"پرس تاب‌خورده (سی‌سا) کتل‌بل","steps":["با پاهای به عرض شانه بایستید؛ کتل‌بل در هر دست هم‌سطح شانه.","یک کتل‌بل را از بالای سر پرس کنید و کتل‌بل دیگر هم‌سطح شانه بماند.","کتل‌بلِ پرس‌شده را هم‌سطح شانه پایین بیاورید و همزمان کتل‌بل دیگر را از بالای سر پرس کنید.","حرکت پرس را یک‌درمیان ادامه دهید تا حالت تاب (سی‌سا) ایجاد شود.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0548":{"name":"کشش بلند سومو کتل‌بل","steps":["بایستید، پاها بازتر از عرض شانه و پنجه‌ها رو به بیرون.","کتل‌بل را با هر دو دست جلوی بدن بگیرید؛ بازوها رو به پایین دراز.","زانوها را خم کنید و لگن را به حالت اسکوات پایین ببرید؛ کمر صاف.","با فشار انفجاری پاشنه‌ها لگن و زانوها را صاف کنید و کتل‌بل را به سمت چانه بکشید.","همزمان با بالاکشیدن کتل‌بل، آرنج‌ها را بالا و باز نگه دارید و کتف‌ها را به هم فشار دهید.","کتل‌بل را به موقعیت شروع برگردانید و برای تعداد دلخواه تکرار کنید."]},
"0549":{"name":"تاب کتل‌بل","steps":["با پاهای به عرض شانه و پنجه‌های کمی رو به بیرون بایستید.","کتل‌بل را با هر دو دست جلوی بدن بگیرید؛ بازوها دراز.","زانوها را کمی خم کنید و از لگن خم شوید؛ باسن را به عقب بدهید.","کتل‌بل را با بازوهای صاف و کمر صاف بین پاها به عقب تاب دهید.","لگن را به جلو هُل دهید و با شتاب ایجادشده از لگن، کتل‌بل را هم‌سطح شانه بالا بیاورید.","اجازه دهید کتل‌بل بین پاها به عقب تاب بخورد و حرکت را برای تعداد دلخواه تکرار کنید."]},
"0550":{"name":"تراستر کتل‌بل","steps":["ایستاده شروع کنید؛ پاها به عرض شانه و کتل‌بل با هر دو دست و کف دست‌ها رو به هم جلوی سینه.","با خم‌کردن زانوها و عقب‌بردن لگن به حالت اسکوات پایین بروید؛ سینه بالا و کمر صاف.","در پایین‌ترین نقطه اسکوات، با فشار انفجاری پاشنه‌ها بلند شوید و همزمان کتل‌بل را از بالای سر پرس کنید.","در بالای حرکت بازوها را قفل کنید؛ آرنج‌ها کاملاً صاف.","کتل‌بل را با برعکس‌کردن حرکت به موقعیت شروع برگردانید؛ آرنج‌ها خم و وزنه به سمت سینه.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0551":{"name":"برخاست ترکی (اسکواتی) کتل‌بل","steps":["به پشت با پاهای دراز دراز بکشید؛ کتل‌بل در دست راست و بازو کاملاً صاف بالای شانه.","زانوی راست را خم کنید و کف پای راست را صاف روی زمین بگذارید؛ پای چپ صاف.","با فشار پای راست، لگن را از زمین بلند کنید و به حالت پل بروید.","پای چپ را زیر بدن سر بخورید؛ زانوی چپ خم و کف پای چپ صاف روی زمین.","تنه را به چپ بچرخانید و دست چپ را برای تکیه به زمین ببرید.","با فشار پای راست و دست چپ، تنه را از زمین بلند کنید و به حالت زانوزده بروید.","از حالت زانوزده بلند شوید و کتل‌بل را صاف بالای سر نگه دارید.","حرکت را برای برگشتن به موقعیت شروع برعکس کنید.","حرکت را در طرف دیگر با کتل‌بل در دست چپ تکرار کنید."]},
"0552":{"name":"کلین دو دست کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را با هر دو دست و کف رو به خودتان جلوی ران‌ها بگیرید.","زانوها را کمی خم کنید و از لگن خم شوید تا کتل‌بل به سمت زمین پایین برود.","لگن و زانوها را با قدرت صاف کنید و با شتاب حاصل، کتل‌بل را به سمت شانه‌ها بکشید.","وقتی کتل‌بل هم‌سطح شانه رسید، مچ‌ها را بچرخانید و آن را در حالت رک بگیرید؛ آرنج‌ها نزدیک بدن و کتل‌بل روی پشت ساعد.","کتل‌بل را به موقعیت شروع برگردانید و برای تعداد دلخواه تکرار کنید."]},
"0553":{"name":"پرس نظامی دو دست کتل‌بل","steps":["با پاهای به عرض شانه بایستید؛ کتل‌بل در هر دست هم‌سطح شانه و کف دست‌ها رو به جلو.","میان‌تنه را منقبض کنید و کتل‌بل‌ها را از بالای سر پرس کنید؛ بازوها کاملاً صاف.","در بالا مکث کنید، سپس کتل‌بل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1345":{"name":"زیربغل دو دست کتل‌بل","steps":["با پاهای به عرض شانه، زانوهای کمی خم بایستید و در هر دست کتل‌بل با کف رو به بدن بگیرید.","از لگن به جلو خم شوید و کمر را صاف و میان‌تنه را منقبض نگه دارید.","کتل‌بل‌ها را به سمت سینه بالا بکشید و کتف‌ها را به هم فشار دهید.","در بالا مکث کنید، سپس کتل‌بل‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0554":{"name":"آسیاب بادی کتل‌بل","steps":["با پاهای به عرض شانه بایستید و کتل‌بل را در دست راست بالای سر بگیرید.","پای چپ را حدود ۴۵ درجه رو به بیرون بچرخانید و پای راست رو به جلو بماند.","تنه را به چپ خم کنید؛ بازوی راست بالای سر صاف و نگاه به کتل‌بل.","تنه را با بازوی راست صاف و دست چپ دراز به پهلو، تا حد ممکن پایین ببرید.","لحظه‌ای مکث کنید، سپس با فشار پای راست و انقباض پهلوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0555":{"name":"درازنشست با بیرون‌دادن پا","steps":["روی لبه میز یا صندلی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","کمی به عقب خم شوید و دست‌ها را برای تکیه روی لبه میز یا صندلی بگذارید.","با انقباض پشت پا، پاها را از زمین بلند و صاف جلوی خود دراز کنید.","در بالا مکث کنید، سپس زانوها را خم و پاها را به‌آرامی به سمت بدن برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0558":{"name":"ماسل‌آپ با ضربه (کیپینگ)","steps":["از میله بارفیکس با دست از پشت و کمی بازتر از عرض شانه آویزان شوید.","میان‌تنه را منقبض کنید و با حرکت تابی شتاب ایجاد کنید.","همزمان با تاب به جلو، با آغاز حرکت از زیربغل و جلوبازو سینه را به سمت هالتر بکشید.","حرکت رو به بالا را ادامه دهید تا سینه به هالتر برسد، سپس با فشار هالتر به پایین و صاف‌کردن بازوها به حالت پارالل بروید.","با خم‌کردن بازوها و کنترل نزول، خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3640":{"name":"کرانچ با لمس زانو","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، کتف‌ها را از زمین بلند کنید و دست راست را به سمت زانوی چپ برسانید.","به موقعیت شروع برگردید و تکرار کنید؛ این‌بار دست چپ به سمت زانوی راست.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"1420":{"name":"اسکوات پرشی زانوزده با هالتر","steps":["روی زمین زانو بزنید؛ پاها به عرض لگن و پنجه‌ها رو به جلو.","هالتر را روی پشت بالایی و روی شانه‌ها نگه دارید.","میان‌تنه و باسن را منقبض کنید، سپس با انفجار به هوا بپرید؛ لگن و زانوها صاف شوند.","همزمان با پرش، با فشار پنجه‌ها مچ پا، زانوها و لگن را کاملاً صاف کنید.","نرم روی زمین فرود بیایید و برای جذب ضربه زانوها را خم کنید.","بلافاصله وارد تکرار بعدی شوید و حرکت اسکوات پرشی را تکرار کنید."]},
"1346":{"name":"کشش زیربغل زانوزده","steps":["روی زمین با زانوهای به عرض لگن زانو بزنید؛ پنجه‌ها رو به عقب.","بازوها را بالای سر دراز کنید و انگشتان را در هم ببافید.","با کمر صاف، به‌آرامی به راست خم شوید تا کشش زیربغل چپ را احساس کنید.","کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس به موقعیت شروع برگردید.","کشش را در سمت چپ تکرار کنید؛ به چپ خم شوید و کشش زیربغل راست را احساس کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"3239":{"name":"پلانک زانوزده با ضربه به شانه (مرد)","steps":["در حالت زانوزده با دست‌های به عرض شانه روی زمین شروع کنید.","پاها را پشت سر روی پنجه‌ها دراز کنید و بدن را به حالت پلانک بلند کنید.","با میان‌تنه منقبض و لگن پایدار، یک دست را از زمین بلند کنید و شانه مخالف را لمس کنید.","دست را به زمین برگردانید و با دست دیگر تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"3211":{"name":"شنا سوئدی زانوزده (مرد)","steps":["روی زمین زانو بزنید؛ دست‌ها به عرض شانه و انگشتان رو به جلو.","پاها را پشت سر دراز کنید و روی پنجه‌ها قرار بگیرید تا بدن از سر تا پاشنه خطی صاف بسازد.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌های نزدیک بدن، بدن را به سمت زمین پایین ببرید.","پایین‌رفتن را ادامه دهید تا سینه کمی بالای زمین برسد، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3288":{"name":"پارالل کره‌ای","steps":["بین دو میله موازی جای بگیرید؛ بازوها دراز و وزن بدن روی آنها.","با خم‌کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.","لحظه‌ای مکث کنید، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3418":{"name":"بارفیکس با پا به شکل L","steps":["میله بارفیکس را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","آویزان شوید؛ بازوها کاملاً صاف و بدن صاف.","زیربغل و جلوبازو را درگیر کنید و با آرنج‌های نزدیک بدن، بدن را به سمت هالتر بکشید.","کشش را ادامه دهید تا چانه از هالتر بالاتر برود.","در بالای حرکت لحظه‌ای مکث کنید، سپس بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3419":{"name":"نشست L روی زمین","steps":["روی زمین بنشینید و پاها را در مقابل خود صاف کنید.","دست‌ها را کنار لگن روی زمین بگذارید؛ انگشتان رو به جلو.","میان‌تنه را منقبض کنید و پاها را صاف از زمین بلند کنید.","تلاش کنید پاها را موازی زمین بیاورید تا بدن حالت L بگیرد.","این حالت را تا جایی که می‌توانید نگه دارید.","پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0562":{"name":"زمین‌ماین ۱۸۰","steps":["با پاهای به عرض شانه بایستید و هالتر را با هر دو دست جلوی سینه بگیرید.","زانوها را کمی خم کنید و تنه را به راست بچرخانید و هالتر را به سمت لگن راست پایین تاب دهید.","در پایین‌ترین نقطه حرکت، سریع جهت را عوض کنید؛ تنه را به چپ بچرخانید و هالتر را به‌صورت مورب بالای بدن به سمت شانه چپ پرتاب کنید.","چرخش را با تعویض طرفین برای تعداد دلخواه تکرار ادامه دهید."]},
"3237":{"name":"نشر جانب زمین‌ماین","steps":["بایستید، پاها به عرض شانه و زانوها کمی خم باشد.","هالتر را با دست از پشت بگیرید و جلوی شانه‌ها قرار دهید.","با میان‌تنه منقبض و کمر صاف، هالتر را از بدن دور و هم‌سطح شانه بالا ببرید.","در بالای حرکت لحظه‌ای مکث کنید، سپس هالتر را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3300":{"name":"پلانش خمیده","steps":["در حالت شنا سوئدی با دست‌های به عرض شانه و بدن صاف شروع کنید.","میان‌تنه را منقبض کنید و وزن را به‌آرامی به جلو منتقل کنید تا شانه‌ها جلوتر از دست‌ها برود.","همزمان با خم‌شدن به جلو، آرنج‌ها کمی خم و بدن صاف بماند.","این حالت را چند ثانیه نگه دارید، سپس به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2271":{"name":"هوک چپ بوکس","steps":["بایستید، پاها به عرض شانه و زانوها کمی خم باشد.","دست چپ را برای محافظت از صورت بالا نگه دارید و دست راست کنار چانه.","لگن را بچرخانید و روی پای چپ بچرخید؛ همزمان دست چپ با حرکت مشت به جلو دراز شود.","برای ایجاد قدرت در مشت، تنه را بچرخانید و عضلات میان‌تنه را درگیر کنید.","بازو را سریع به موقعیت شروع برگردانید و برای تعداد دلخواه تکرار کنید."]},
"0570":{"name":"کشیدن پا روی میز صاف","steps":["روی میز صاف بنشینید و پاها را صاف جلوی خود دراز کنید.","دست‌ها را برای تکیه کنار لگن روی میز بگذارید.","شکم را منقبض کنید و پاها را از زمین بلند کنید؛ زانوها به سمت سینه.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1576":{"name":"کشش همسترینگ با پای بلند","steps":["به پشت دراز بکشید؛ پاها دراز.","یک زانو را خم کنید و به سمت سینه بیاورید؛ ران یا ساق را با دست بگیرید.","پا را در حالت بلند تا حد ممکن صاف کنید.","کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.","حرکت را با پای دیگر تکرار کنید."]},
"2287":{"name":"پرس پا یک‌درمیان دستگاه","steps":["صندلی و سکوی پا دستگاه را روی موقعیت دلخواه تنظیم کنید.","روی دستگاه با کمر چسبیده به پشتی و پاها روی سکوی پا بنشینید.","برای تثبیت، دست‌ها را روی دسته‌ها یا کناره‌های دستگاه بگذارید.","یک پا را به سکوی پا فشار دهید تا تقریباً کاملاً صاف شود.","لحظه‌ای مکث کنید، سپس پا را به‌آرامی خم و به موقعیت شروع برگردانید.","حرکت را با پای دیگر تکرار کنید.","به‌تناوب پاها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"0571":{"name":"زیربغل نشسته دست جمع یک‌درمیان دستگاه","steps":["ارتفاع صندلی و جای پد پا را تنظیم کنید تا زاویه‌گیری درست باشد.","روی دستگاه با کمر صاف و کف پاها صاف روی پد پا بنشینید.","دسته‌ها را با گریپ باریک و کف دست‌ها رو به هم بگیرید.","در طول حرکت سینه بالا و شانه‌ها به عقب بمانند.","یک دسته را به سمت تنه بکشید و دسته دیگر ثابت بماند.","در انتهای حرکت کتف‌ها را به هم فشار دهید.","دسته را به‌آرامی به موقعیت شروع برگردانید و با طرف دیگر تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0572":{"name":"بارفیکس دست جمع دستگاه کمکی","steps":["مقاومت دستگاه را روی میزان دلخواه تنظیم کنید.","روی سکوی پا بایستید و دسته‌ها را با دست از پشت و کمی بازتر از عرض شانه بگیرید.","با بازوهای کاملاً صاف آویزان شوید؛ بدن صاف.","عضلات پشت را منقبض کنید و با پیشتازی سینه، بدن را به سمت دسته‌ها بکشید.","کشش را ادامه دهید تا چانه از دسته‌ها بالاتر برود.","در بالای حرکت لحظه‌ای مکث کنید، سپس بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0573":{"name":"اکستنشن کمر دستگاه","steps":["دستگاه را متناسب با اندازه بدن و دامنه حرکتی خود تنظیم کنید.","روی دستگاه با کمر چسبیده به پد و پاها ثابت بنشینید.","دست‌ها را روی دسته‌ها یا میله‌های گریپ بگذارید.","میان‌تنه را منقبض کنید و به‌آرامی به جلو خم شوید؛ کمر کمی گِرد شود.","در پایین‌ترین موقعیت مکث کنید و کشش کمر پایین را احساس کنید.","با عضلات پشت، تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0574":{"name":"زیربغل خم دستگاه","steps":["بایستید، پاها به عرض شانه و زانوها کمی خم باشد.","هالتر را با دست از پشت و کمی بازتر از عرض شانه نگه دارید.","از لگن به جلو خم شوید؛ کمر صاف و سینه بالا.","هالتر را به سمت سینه پایینی بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت لحظه‌ای مکث کنید، سپس هالتر را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3200":{"name":"زیربغل خم با دسته V دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روبه‌روی دستگاه جای بگیرید.","دسته V را با دست از پشت بگیرید؛ کمر صاف و زانوها کمی خم.","دسته V را به سمت شکم بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت مکث کنید، سپس وزنه را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0575":{"name":"جلوبازو دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید طوری که کمر به پد چسبیده باشد.","دسته‌ها را با دست از جلو و کف رو به بالا بگیرید؛ آرنج‌ها نزدیک پهلوها.","بازدم کنید و دسته‌ها را با انقباض جلوبازو بالا بکشید.","در بالای حرکت لحظه‌ای مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دسته‌ها را با بازوهای کاملاً صاف به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2289":{"name":"پرس ساق دستگاه","steps":["صندلی دستگاه را طوری تنظیم کنید که شانه‌ها در راستای پد اهرم باشند.","پنجه‌ها را روی پد اهرم بگذارید؛ پاشنه‌ها از لبه آویزان.","برای پایداری، دسته‌ها یا تکیه‌گاه‌های جانبی را بگیرید.","پد اهرم را با باز‌کردن مچ پاها به پایین فشار دهید؛ ساق‌ها منقبض.","در پایین‌ترین نقطه حرکت لحظه‌ای مکث کنید.","به‌آرامی با بالا‌بردن دوباره پاشنه‌ها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0577":{"name":"پرس سینه دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر صاف چسبیده به پد روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و آرنج‌ها را با زاویه ۹۰ درجه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو پرس کنید و در طول حرکت بازدم کنید.","در انتهای حرکت مکث کوتاهی کنید، سپس با دم به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0576":{"name":"پرس سینه دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر صاف چسبیده به پد روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و آرنج‌ها را با زاویه ۹۰ درجه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو پرس کنید و در طول حرکت بازدم کنید.","در انتهای حرکت مکث کوتاهی کنید، سپس با دم به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0578":{"name":"ددلیفت دستگاه","steps":["ارتفاع صندلی و سکوی پا را روی موقعیت دلخواه تنظیم کنید.","روی دستگاه با کمر چسبیده به پد و کف پاها صاف روی سکوی پا بنشینید.","برای تثبیت، دسته‌ها یا کناره‌های صندلی را بگیرید.","باسن و پشت پا را منقبض کنید و با فشار پاشنه‌ها وزنه را بلند کنید.","کمر صاف باشد و از گرد‌کردن شانه‌ها پرهیز کنید.","در بالای حرکت لگن را کاملاً صاف کنید و باسن را منقبض نگه دارید.","وزنه را با کنترل پایین ببرید و کشش را در باسن و پشت پا حفظ کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1300":{"name":"پرس سینه زیرسینه دستگاه","steps":["ارتفاع صندلی و پشتی دستگاه را در وضعیت راحت تنظیم کنید.","روی دستگاه بنشینید، کمر به پشتی چسبیده و کف پاها صاف روی زمین باشد.","دسته‌ها را با دست از پشت بگیرید و دست‌ها را کمی بازتر از عرض شانه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو و دور از بدن پرس کنید.","دسته‌ها را با کمی خم در آرنج‌ها به‌آرامی به سمت سینه برگردانید.","در پایین‌ترین نقطه مکث کنید، سپس دسته‌ها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1253":{"name":"ساق پا دونکی دستگاه","steps":["دستگاه را در ارتفاع مناسب بدن خود تنظیم کنید.","روبه‌روی دستگاه جای بگیرید؛ پنجه‌ها روی سکوی پا و پاشنه‌ها از لبه آویزان.","برای پایداری، دست‌ها را روی دسته‌ها یا میله‌های تکیه بگذارید.","ساق‌ها را منقبض کنید و با فشار پنجه‌ها پاشنه‌ها را تا حد ممکن بالا ببرید.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاشنه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0579":{"name":"زیربغل از جلو دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ زانوها زیر پدها و کف پاها صاف روی زمین.","دسته‌ها را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","صاف بنشینید؛ سینه بالا، شانه‌ها به عقب و قوس ملایم در کمر.","زیربغل را درگیر کنید و دسته‌ها را به سمت سینه پایین بکشید؛ کتف‌ها به هم فشار داده شوند.","در پایین‌ترین نقطه حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0580":{"name":"شراگ بدون گریپ دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید.","دسته‌ها را با کف دست‌ها رو به داخل و بازوهای کاملاً صاف بگیرید.","با کمر صاف، بازدم کنید و شانه‌ها را تا حد ممکن بالا ببرید.","انقباض را لحظه‌ای نگه دارید، سپس نفس بگیرید و شانه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1439":{"name":"شراگ بدون گریپ دستگاه نسخه ۲","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید طوری که کمر به پد چسبیده باشد.","دسته‌ها یا میله‌ها را با دست از پشت بگیرید؛ بازوها صاف.","با کمر صاف، شانه‌ها را تا حد ممکن به سمت گوش‌ها بالا ببرید.","انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2288":{"name":"گیرش دست دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و دسته‌های دستگاه را بگیرید.","کمر صاف و کف پاها صاف روی زمین بماند.","بازدم کنید و دسته‌ها را با انقباض ساعدها فشار دهید.","انقباض را یک ثانیه نگه دارید، سپس به‌آرامی رها کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1615":{"name":"جلوبازو چکشی لاری دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید.","بازوها را روی پد لاری بگذارید و مطمئن شوید سینه به آن چسبیده است.","دسته‌ها را با گریپ چکشی بگیرید (کف دست‌ها رو به هم).","بازوها را ثابت نگه دارید، بازدم کنید و دسته‌ها را به سمت شانه‌ها بکشید.","در بالای حرکت مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دسته‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0581":{"name":"زیربغل بلند دستگاه","steps":["ارتفاع صندلی و سکوی پا را در وضعیت راحت تنظیم کنید.","روی دستگاه با سینه چسبیده به پد و کف پاها صاف روی سکوی پا بنشینید.","دسته‌ها را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دسته‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.","در اوج حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2286":{"name":"اکستنشن ران دستگاه نسخه ۲","steps":["دستگاه را متناسب با بدن خود تنظیم کنید و با کمر چسبیده به پشتی روی آن بنشینید.","پاها را روی رکاب‌ها بگذارید و برای پایداری دسته‌ها را بگیرید.","باسن و پشت پا را منقبض کنید، سپس به تکیه‌گاه پا فشار دهید تا لگن صاف و پاها به عقب بلند شوند.","در بالای حرکت مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2611":{"name":"پرس پا افقی تک‌پا دستگاه","steps":["صندلی دستگاه را طوری تنظیم کنید که با پاها روی پد، زانوها با زاویه ۹۰ درجه خم باشند.","روی دستگاه بنشینید؛ کمر به پشتی و پاها به عرض شانه روی پد پا.","برای تثبیت، دست‌ها را روی دسته‌ها یا کناره‌های دستگاه بگذارید.","پد پا را با دراز‌کردن پا از بدن دور کنید؛ کمر به پشتی چسبیده.","در حالت کاملاً صاف مکث کنید، سپس پا را برای برگشتن به موقعیت شروع به‌آرامی خم کنید.","برای تعداد دلخواه تکرار کنید، سپس پا را عوض کنید."]},
"1299":{"name":"پرس سینه بالاسینه دستگاه","steps":["صندلی و پشتی دستگاه را در وضعیت راحت تنظیم کنید.","روی دستگاه بنشینید، کمر به پشتی چسبیده و کف پاها صاف روی زمین باشد.","دسته‌ها را با دست از پشت بگیرید و دست‌ها را کمی بازتر از عرض شانه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو و دور از بدن پرس کنید.","لحظه‌ای مکث کنید، سپس آرنج‌ها را خم و دسته‌ها را به‌آرامی به سمت سینه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1479":{"name":"پرس سینه بالاسینه دستگاه نسخه ۲","steps":["ارتفاع صندلی و زاویه پشتی دستگاه را در وضعیت راحت تنظیم کنید.","روی دستگاه بنشینید، کمر به پشتی چسبیده و کف پاها صاف روی زمین باشد.","دسته‌ها را با دست از پشت بگیرید و دست‌ها را کمی بازتر از عرض شانه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو و دور از بدن پرس کنید؛ بدون قفل‌کردن آرنج‌ها.","در حالت کاملاً صاف مکث کنید، سپس آرنج‌ها را خم و دسته‌ها را به‌آرامی به سمت سینه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0582":{"name":"پشت پا زانوزده دستگاه","steps":["دستگاه را متناسب با بدن تنظیم کنید و وزنه دلخواه را انتخاب کنید.","رو به پایین روی دستگاه زانو بزنید؛ زانوها روی پد و پاها زیر پدها ثابت.","برای تثبیت، دسته‌ها یا لبه‌های دستگاه را بگیرید.","تنه را ثابت نگه دارید، بازدم کنید و با خم‌کردن زانوها پاها را به سمت باسن بکشید.","در بالای حرکت مکث کنید و پشت پا را منقبض نگه دارید.","نفس بگیرید و پاها را با زانوهای کاملاً صاف به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0583":{"name":"چرخش زانوزده دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ زانوها روی پدها و تنه رو به جلو.","برای تثبیت، دسته‌ها یا لبه‌های دستگاه را بگیرید.","با میان‌تنه منقبض، تنه را تا حد ممکن راحت به یک طرف بچرخانید.","لحظه‌ای مکث کنید، سپس به‌آرامی به موقعیت شروع برگردید.","چرخش را به طرف مخالف تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0584":{"name":"نشر جانب دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید طوری که کمر به پد چسبیده باشد.","دسته‌ها را با دست از پشت بگیرید و بازوها را صاف نگه دارید.","بازدم کنید و بازوها را به طرفین بالا ببرید تا موازی زمین شوند.","در بالا مکث کنید، سپس نفس بگیرید و بازوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0585":{"name":"جلو پا دستگاه","steps":["ارتفاع صندلی و پشتی دستگاه را متناسب با بدن خود تنظیم کنید.","روی دستگاه با کمر چسبیده به پشتی و پاها روی پد پا بنشینید.","برای تثبیت، دسته‌ها یا میله‌های جانبی را بگیرید.","با صاف‌کردن زانوها پاها را به جلو دراز کنید و وزنه را بلند کنید.","در بالا مکث کنید، سپس وزنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0586":{"name":"پشت پا خوابیده دستگاه","steps":["دستگاه را متناسب با بدن تنظیم کنید و وزنه دلخواه را انتخاب کنید.","رو به زمین روی دستگاه دراز بکشید؛ پاها صاف و پاشنه‌ها به اهرم پددار.","برای تثبیت، دسته‌ها یا لبه‌های دستگاه را بگیرید.","تنه ثابت بماند و همزمان با بازدم، پاها تا حد ممکن بالا کشیده شوند؛ بدون بلندشدن لگن از پد.","در حالت انقباضی کمی مکث کنید و پشت پا را منقبض نگه دارید.","نفس بگیرید و اهرم دستگاه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3195":{"name":"پشت پا خوابیده دو-یک پا دستگاه","steps":["دستگاه را متناسب با بدن خود تنظیم کنید و با کمر چسبیده به پشتی روی آن بنشینید.","پاها را روی پد اهرم، کمی بالای مچ قرار دهید.","برای تکیه، دسته‌های کناری دستگاه را بگیرید.","تنه ثابت بماند و همزمان با بازدم، پاها به سمت باسن جمع شوند.","در بالا مکث کنید، سپس نفس بگیرید و پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0587":{"name":"پرس نظامی دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر چسبیده به پشتی روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و دست‌ها را کمی بازتر از عرض شانه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید، اما آرنج‌ها را قفل نکنید.","در بالای حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0588":{"name":"زیربغل نشسته دست جمع دستگاه","steps":["ارتفاع صندلی و تکیه‌گاه پاها را برای فرم درست تنظیم کنید.","روی دستگاه بنشینید؛ کف پاها صاف روی رکاب‌ها و زانوها کمی خم.","دسته‌ها را با گریپ باریک و کف دست‌ها رو به هم بگیرید.","کمر صاف باشد و کمی به جلو خم شوید.","دسته‌ها را به سمت تنه بکشید و کتف‌ها را به هم فشار دهید.","در اوج حرکت لحظه‌ای مکث کنید.","دسته‌ها را به‌آرامی رها کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0589":{"name":"زیربغل خم تک‌دست دستگاه","steps":["با پاهای به عرض شانه، زانوهای کمی خم بایستید و هالتر را با دست از پشت بگیرید.","از لگن به جلو خم شوید؛ کمر صاف و سر بالا.","اجازه دهید هالتر با بازوهای کاملاً صاف جلوی شما آویزان باشد.","هالتر را با آرنج‌های نزدیک بدن به سمت سینه بالا بکشید.","در بالای حرکت کتف‌ها را به هم فشار دهید.","هالتر را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1356":{"name":"زیربغل بلند جانبی تک‌دست دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روبه‌روی دستگاه جای بگیرید.","دسته را با یک دست بگیرید و کمر را صاف نگه دارید.","دسته را با آرنج نزدیک پهلو به سمت بدن بکشید.","در بالای حرکت عضلات پشت را منقبض کنید.","دسته را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1347":{"name":"زیربغل از بالا جانبی دست باز دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ سینه چسبیده به پد و کف پاها صاف روی زمین.","دسته را با دست از پشت بگیرید و بازو را با کمی خم در آرنج کاملاً دراز کنید.","دسته را پایین و ضربدری به سمت لگن مخالف بکشید؛ در پایین حرکت زیربغل منقبض شود.","دسته را با بازوی کاملاً صاف به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0590":{"name":"پرس سرشانه تک‌دست دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید طوری که کمر به پد چسبیده باشد.","دسته اهرم را با یک دست بگیرید و آرنج را با زاویه ۹۰ درجه قرار دهید.","اهرم را تا صاف‌شدن کامل بازو به بالا پرس کنید.","در بالا مکث کنید، سپس اهرم دستگاه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس به دست دیگر بروید."]},
"0591":{"name":"پارالل پشت‌بازو دستگاه","steps":["دستگاه را در ارتفاع مناسب تنظیم کنید و بدن خود را در موقعیت ثابت کنید.","دسته‌ها را با دست از پشت بگیرید و بدن را طوری قرار دهید که بازوها کاملاً صاف باشند.","بدن را با خم‌کردن آرنج‌ها پایین ببرید؛ بازوها نزدیک پهلوها.","پایین‌رفتن را ادامه دهید تا بازوها موازی زمین شوند.","لحظه‌ای مکث کنید، سپس با صاف‌کردن آرنج‌ها خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0592":{"name":"جلوبازو لاری دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید.","بازوها را روی پد بگذارید و دسته‌ها را با دست از جلو بگیرید.","کمر صاف باشد و آرنج‌ها روی پد قرار بگیرند.","بازدم کنید و با انقباض جلوبازو ساعدها را به سمت بازوها جمع کنید.","در بالای حرکت لحظه‌ای مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دسته‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1614":{"name":"جلوبازو لاری دستگاه نسخه ۲","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ بازوها روی پد و سینه چسبیده به تکیه‌گاه.","دسته‌ها را با دست از جلو و کمی بازتر از عرض شانه بگیرید.","بازوها ثابت بمانند و همزمان با انقباض جلوبازو و کشیدن دسته‌ها به سمت شانه‌ها، بازدم کنید.","در بالای حرکت لحظه‌ای مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دسته‌ها را با بازوهای کاملاً صاف به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2285":{"name":"پول‌اور دستگاه","steps":["صندلی و دسته‌های دستگاه را در وضعیت راحت تنظیم کنید.","روی دستگاه با کمر چسبیده به پد بنشینید و دسته‌ها را با دست از پشت بگیرید.","بازوها را کمی خم و میان‌تنه را منقبض نگه دارید.","دسته‌ها را به‌آرامی به سمت سینه بکشید و زیربغل را منقبض کنید.","در اوج انقباض مکث کنید، سپس به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2736":{"name":"زیربغل از بالا با گریپ برعکس دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ زانوها زیر پدها و کف پاها صاف روی زمین.","دسته‌ها را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","صاف بنشینید؛ سینه بیرون، شانه‌ها به عقب و قوس ملایم در کمر.","دسته‌ها را با پیشتازی آرنج‌ها به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.","در پایین‌ترین نقطه حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1616":{"name":"جلوبازو لاری با گریپ برعکس دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید.","دسته‌ها را با دست از جلو و کف رو به بالا بگیرید.","بازوها را روی پد لاری بگذارید و مطمئن شوید آرنج‌ها کاملاً صاف هستند.","بازوها را ثابت نگه دارید، بازدم کنید و دسته‌ها را به سمت شانه‌ها بکشید.","در بالای حرکت لحظه‌ای مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و دسته‌ها را با آرنج‌های کاملاً صاف به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1348":{"name":"زیربغل قائم با گریپ برعکس دستگاه","steps":["ارتفاع صندلی و جای پد پا را تنظیم کنید تا زاویه‌گیری درست باشد.","روی دستگاه بنشینید؛ سینه چسبیده به پد و کف پاها روی پد پا.","دسته‌ها را با دست از جلو و کف رو به بالا بگیرید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دسته‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت مکث کنید، سپس رها کنید و بازوها را به موقعیت شروع صاف کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0593":{"name":"هایپرااکستنشن برعکس دستگاه","steps":["دستگاه را متناسب با بدن خود تنظیم کنید و پاها را روی پدها ثابت کنید.","رو به زمین روی دستگاه دراز بکشید؛ تنه بالایی از لبه آویزان و لگن روی پد.","بازوها را روی سینه ضربدری کنید یا پشت سر بگذارید.","باسن و پشت پا را منقبض کنید و پاها را بالا ببرید تا موازی زمین شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1349":{"name":"زیربغل تی‌بار با گریپ برعکس دستگاه","steps":["ارتفاع صندلی و موقعیت پد پا را روی دستگاه تنظیم کنید.","روی دستگاه بنشینید؛ سینه چسبیده به پد و کف پاها روی پد پا.","دسته‌ها را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دسته‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت مکث کنید، سپس رها کنید و بازوها را به موقعیت شروع صاف کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2315":{"name":"ساق پا چرخشی دستگاه","steps":["ارتفاع صندلی را طوری تنظیم کنید که زانوها کمی خم و کف پاها صاف روی پد پا باشد.","پنجه‌ها را روی پد پا بگذارید؛ پاشنه‌ها از لبه آویزان.","برای تثبیت، دسته‌ها یا لبه‌های دستگاه را بگیرید.","با فشار پنجه‌ها، پاشنه‌ها را تا حد ممکن بالا ببرید.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاشنه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2335":{"name":"پرس ساق نشسته دستگاه","steps":["صندلی دستگاه را طوری تنظیم کنید که شانه‌ها در راستای پد اهرم باشند.","پنجه‌ها را روی قسمت پایینی سکو بگذارید و زانوها را زیر پد اهرم قرار دهید.","برای پایداری، دسته‌های کنار صندلی را بگیرید.","پد اهرم را با باز‌کردن مچ پاها به پایین فشار دهید و پاشنه‌ها را تا حد ممکن بالا ببرید.","در بالای حرکت مکث کنید، سپس پاشنه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0594":{"name":"ساق پا نشسته دستگاه","steps":["ارتفاع صندلی را طوری تنظیم کنید که زانوها کمی خم و کف پاها صاف روی پد پا باشد.","پنجه‌ها را روی پد پا بگذارید؛ پاشنه‌ها از لبه آویزان.","برای تثبیت، دسته‌ها یا کناره‌های صندلی را بگیرید.","با فشار پنجه‌ها پاشنه‌ها را تا حد ممکن بالا ببرید.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاشنه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1452":{"name":"کرانچ نشسته دستگاه","steps":["روی دستگاه با کمر چسبیده به پد و کف پاها صاف روی زمین بنشینید.","دسته‌ها را بگیرید یا دست‌ها را برای تکیه روی پدهای کناری بگذارید.","شکم را منقبض کنید و به‌آرامی به عقب خم شوید؛ پد همراه شما حرکت کند.","وقتی تنه ۴۵ درجه شد، شکم را منقبض کنید و به جلو کرانچ بزنید؛ سینه به سمت زانوها.","در بالا مکث کنید، سپس به‌آرامی رها کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0595":{"name":"کرانچ نشسته دستگاه (با پد سینه)","steps":["ارتفاع صندلی و موقعیت پد سینه را راحت تنظیم کنید.","روی دستگاه با کمر چسبیده به پد سینه و کف پاها صاف روی زمین بنشینید.","برای پایداری، دسته‌ها یا میله‌های جانبی را بگیرید.","شکم را منقبض کنید و به‌آرامی به عقب خم شوید؛ پد سینه همراه شما حرکت کند.","در حداکثر انقباض مکث کنید و کشش شکم را حس کنید.","به‌آرامی با انقباض شکم و کشیدن خود به بالا به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3760":{"name":"کرانچ نشسته دستگاه نسخه ۲","steps":["روی دستگاه با کمر چسبیده به پد و پاها زیر پدها ثابت بنشینید.","دست‌ها را برای تکیه روی دسته‌ها یا کناره‌های صندلی بگذارید.","شکم را منقبض کنید و به‌آرامی به جلو کرانچ بزنید؛ سینه را به سمت زانوها ببرید.","در بالای حرکت مکث کنید و عضلات شکم را منقبض نگه دارید.","به‌آرامی به موقعیت شروع برگردید و اجازه دهید کمر کمی گِرد شود.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1451":{"name":"پارالل نشسته دستگاه","steps":["ارتفاع صندلی را طوری تنظیم کنید که کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم باشند.","دسته‌های دستگاه را با کف دست‌ها رو به پایین و بازوهای کاملاً صاف بگیرید.","بدن را با خم‌کردن آرنج‌ها به‌آرامی پایین ببرید تا بازوها موازی زمین شوند.","لحظه‌ای مکث کنید، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0596":{"name":"قفسه سینه نشسته دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید طوری که کمر به پد چسبیده باشد.","دسته‌ها را با گریپ رو به پایین بگیرید و آرنج‌ها را کمی خم نگه دارید.","بازدم کنید و دسته‌ها را به جلو فشار دهید تا جلوی سینه به هم برسند.","لحظه‌ای مکث کنید و عضلات سینه را منقبض نگه دارید.","نفس بگیرید و به‌آرامی به موقعیت شروع برگردید تا عضلات سینه کشیده شوند.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3759":{"name":"گودمورنینگ نشسته دستگاه","steps":["ارتفاع صندلی را طوری تنظیم کنید که لگن کمی بالاتر از زانوها باشد.","روی دستگاه با کمر چسبیده به پد و کف پاها صاف روی رکاب‌ها بنشینید.","برای تثبیت، دسته‌ها یا کناره‌های صندلی را بگیرید.","با کمر صاف، به‌آرامی از لگن به جلو خم شوید تا تنه بالایی موازی زمین شود.","لحظه‌ای مکث کنید، سپس با فشار باسن و پشت پا به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0597":{"name":"دورکننده ران نشسته دستگاه","steps":["ارتفاع صندلی را طوری تنظیم کنید که زانوها با زاویه ۹۰ درجه خم شوند.","روی دستگاه با کمر چسبیده به پشتی و پاها روی رکاب‌ها بنشینید.","برای پایداری، دست‌ها را روی دسته‌های جانبی بگذارید.","دورکننده‌های ران را منقبض کنید و پاها را آرام از خط وسط بدن دور کنید.","در انتهای حرکت مکث کنید، سپس پاها را به‌آرامی به هم و به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0598":{"name":"نزدیک‌کننده ران نشسته دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر چسبیده به پشتی روی دستگاه جای بگیرید.","پاها را روی رکاب‌ها بگذارید و برای پایداری دسته‌ها را بگیرید.","نزدیک‌کننده‌های ران را منقبض کنید و پاها را به‌آرامی به هم برسانید؛ داخل ران‌ها را فشار دهید.","در اوج انقباض مکث کنید، سپس به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0599":{"name":"پشت پا نشسته دستگاه","steps":["دستگاه را متناسب با بدن خود تنظیم کنید و با کمر چسبیده به پشتی روی آن بنشینید.","ساق‌ها را زیر اهرم پددار، کمی بالای مچ قرار دهید.","برای تکیه، دسته‌های کناری دستگاه را بگیرید.","ران‌ها ثابت بمانند و همزمان با بازدم، ساق‌ها تا حد ممکن بالا کشیده شوند.","در حالت انقباضی کمی مکث کنید و پشت پا را منقبض نگه دارید.","نفس بگیرید و اهرم دستگاه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0600":{"name":"بلندکردن پا با کرانچ نشسته دستگاه","steps":["روی دستگاه با کمر چسبیده به پشتی و پاها روی رکاب‌ها بنشینید.","برای تثبیت، دسته‌ها یا میله‌های جانبی را بگیرید.","شکم را منقبض کنید و پاها را به‌آرامی به سمت سینه بالا ببرید و همزمان تنه را به جلو جمع کنید.","در بالا مکث کنید، سپس پاها و تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0602":{"name":"نشر برعکس نشسته دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ سینه چسبیده به پد و کف پاها صاف روی زمین.","دسته‌ها را با دست از پشت بگیرید و بازوها را کمی خم نگه دارید.","بازدم کنید و در حین کشیدن دسته‌ها به عقب و بیرون، کتف‌ها را به هم فشار دهید.","در اوج انقباض مکث کنید، سپس نفس بگیرید و به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0601":{"name":"نشر برعکس نشسته دستگاه (گریپ موازی)","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ سینه چسبیده به پد و کف پاها صاف روی زمین.","دسته‌ها را با گریپ موازی و کف دست‌ها رو به هم بگیرید؛ بازوها کمی خم.","بازدم کنید و در حین کشیدن دسته‌ها به عقب و بیرون، کتف‌ها را به هم فشار دهید.","در اوج انقباض مکث کنید، سپس نفس بگیرید و به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1350":{"name":"زیربغل نشسته دستگاه","steps":["ارتفاع صندلی و تکیه‌گاه پا را در وضعیت راحت تنظیم کنید.","روی دستگاه با سینه چسبیده به پد و پاها روی رکاب‌ها بنشینید.","دسته‌ها را با دست از پشت و به عرض شانه بگیرید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دسته‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.","در اوج حرکت لحظه‌ای مکث کنید.","دسته‌ها را به‌آرامی رها کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1385":{"name":"ساق پا اسکوات نشسته روی دستگاه پرس پا","steps":["صندلی دستگاه پرس پا را طوری تنظیم کنید که با پاها روی پد، زانوها کمی خم باشند.","روی دستگاه با کمر چسبیده به پشتی بنشینید؛ کف پاها صاف روی پد پا به عرض شانه.","پنجه‌ها و کف پاها را روی پد پا بگذارید؛ پاشنه‌ها از لبه بیرون.","دسته‌های ایمنی را رها کنید و پد پا را با دراز‌کردن زانوها از خود دور کنید.","وقتی زانوها کاملاً صاف شدند، پاشنه‌ها را با کنترل ساق به‌آرامی پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس پد پا را با باز‌کردن ساق‌ها به بالا برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0603":{"name":"پرس سرشانه دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر چسبیده به پشتی روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و دست‌ها را هم‌سطح شانه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به بالا پرس کنید، اما آرنج‌ها را قفل نکنید.","در بالای حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0869":{"name":"پرس سرشانه دستگاه نسخه ۲","steps":["ارتفاع صندلی و پشتی دستگاه را در وضعیت راحت تنظیم کنید.","روی دستگاه بنشینید، کمر به پشتی چسبیده و کف پاها صاف روی زمین باشد.","دسته‌های دستگاه را با دست از پشت و کمی بازتر از عرض شانه بگیرید.","دسته‌ها را به بالا و جلو پرس کنید تا بازوها کاملاً صاف شوند، اما قفل نشوند.","در بالای حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2318":{"name":"پرس سرشانه دستگاه نسخه ۳","steps":["ارتفاع صندلی و پشتی دستگاه را در وضعیت راحت تنظیم کنید.","روی دستگاه بنشینید، کمر به پشتی چسبیده و کف پاها صاف روی زمین باشد.","دسته‌های دستگاه را با دست از پشت و کمی بازتر از عرض شانه بگیرید.","دسته‌ها را به بالا و جلو پرس کنید تا بازوها کاملاً صاف شوند، اما قفل نشوند.","در بالای حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0604":{"name":"شراگ دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر چسبیده به پد روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و بازوها را صاف نگه دارید.","با کمر صاف، شانه‌ها را تا حد ممکن به سمت گوش‌ها بالا ببرید.","انقباض را لحظه‌ای نگه دارید، سپس شانه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0605":{"name":"ساق پا ایستاده دستگاه","steps":["دستگاه را متناسب با قد خود تنظیم کنید و با پاهای به عرض شانه بایستید.","شانه‌ها را زیر پدها قرار دهید و برای پایداری دسته‌ها را بگیرید.","با کشیدن مچ پا، پاشنه‌ها را تا حد ممکن بالا ببرید.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاشنه‌ها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3758":{"name":"پرس سینه ایستاده دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ کف پاها صاف روی زمین.","دسته‌ها را با دست از پشت بگیرید و دست‌ها را هم‌سطح سینه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو پرس کنید؛ آرنج‌ها کمی خم.","لحظه‌ای مکث کنید، سپس دسته‌ها را با کنترل کامل در طول حرکت به‌آرامی به سمت سینه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0606":{"name":"زیربغل تی‌بار دستگاه","steps":["ارتفاع صندلی و جای پد پا را تنظیم کنید تا زاویه‌گیری درست باشد.","روی دستگاه بنشینید؛ سینه چسبیده به پد و کف پاها روی پد پا.","دسته‌ها را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دسته‌ها را به سمت تنه بکشید و کتف‌ها را به هم فشار دهید.","در اوج انقباض مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1351":{"name":"زیربغل تی‌بار با گریپ برعکس دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ سینه چسبیده به پد و کف پاها صاف روی زمین.","دسته‌ها را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","کمر را صاف و عضلات میان‌تنه را منقبض نگه دارید.","دسته‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت مکث کنید، سپس رها کنید و بازوها را به موقعیت شروع صاف کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0607":{"name":"پشت‌بازو دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه بنشینید طوری که کمر به پد چسبیده باشد.","دسته‌ها را با دست از پشت بگیرید و بازوها را کاملاً جلوی خود دراز کنید.","بازوها ثابت بمانند و دسته‌ها با خم‌کردن آرنج‌ها به‌آرامی به سمت پیشانی پایین برود.","در پایین‌ترین نقطه مکث کنید، سپس دسته‌ها را با صاف‌کردن بازوها به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1313":{"name":"زیربغل تک‌طرفه دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روبه‌روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و کمر را صاف نگه دارید.","دسته‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.","در اوج حرکت مکث کنید، سپس به‌آرامی رها کنید و بازوها را به موقعیت شروع صاف کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0609":{"name":"پل لندن با طناب","steps":["طناب را به نقطه اتصال بلند وصل کنید.","پشت به نقطه اتصال بایستید و پاها را به عرض شانه باز کنید.","طناب را با دست از پشت و کف رو به پایین بگیرید.","کمی به جلو خم شوید؛ کمر صاف و میان‌تنه منقبض.","طناب را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.","در اوج حرکت مکث کنید، سپس کشش را به‌آرامی رها کرده و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3013":{"name":"پل باسن کوتاه روی زمین","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","بازوها را کنار بدن با کف دست‌ها رو به پایین قرار دهید.","باسن و میان‌تنه را منقبض کنید، سپس لگن را از زمین بلند کنید تا بدن از زانو تا شانه خطی صاف بسازد.","در بالای حرکت مکث کنید و باسن را منقبض نگه دارید.","لگن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1352":{"name":"کرانچ کمر","steps":["به شکم دراز بکشید؛ پاها دراز و بازوها کنار بدن.","باسن و پشت پا را منقبض کنید و تنه بالایی را به‌آرامی از زمین بلند کنید؛ کمر به بالا گِرد شود.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3582":{"name":"لانژ با پرش","steps":["ایستاده شروع کنید و پاها را به عرض شانه باز کنید.","با پای راست یک قدم به جلو بردارید و بدن را به حالت لانژ پایین ببرید.","با هُل پای راست به هوا بپرید و در هوا جای پاها را عوض کنید.","با پای چپ جلو نرم فرود بیایید و فوراً بدن را به حالت لانژ پایین ببرید.","برای تعداد دلخواه تکرار، لانژ و پرش را یک‌درمیان ادامه دهید."]},
"1688":{"name":"لانژ با چرخش","steps":["ایستاده شروع کنید و پاها را به عرض شانه باز کنید.","با پای راست یک قدم به جلو بردارید و بدن را به حالت لانژ پایین ببرید.","همزمان با لانژ، تنه را به راست بچرخانید و آرنج چپ را به سمت زانوی راست ببرید.","لحظه‌ای مکث کنید، سپس به موقعیت شروع برگردید.","در طرف دیگر با گام پای چپ به جلو و چرخش تنه به چپ تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0613":{"name":"کشش چارسر خوابیده (از پهلو)","steps":["به پهلو دراز بکشید؛ پاها صاف.","پای بالایی را خم کنید و مچ یا کف پا را با دست بگیرید.","مچ یا کف پا را به‌آرامی به سمت باسن بکشید تا کشش چهارسر ران را احساس کنید.","کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.","کشش را رها کنید و در طرف دیگر تکرار کنید."]},
"2312":{"name":"آرنج به زانوی مخالف","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","شکم را منقبض کنید و تنه را از زمین بلند کنید؛ آرنج راست به سمت زانوی چپ.","همزمان پای راست را صاف دراز کنید و از زمین بلند کنید.","لحظه‌ای مکث کنید، سپس به موقعیت شروع برگردید.","حرکت را تکرار کنید؛ این‌بار آرنج چپ به سمت زانوی راست و پای چپ صاف شود.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0620":{"name":"بلندکردن پا روی میز صاف","steps":["روی میز صاف دراز بکشید و کمر به آن چسبیده باشد.","برای تکیه، دست‌ها را زیر باسن بگذارید.","پاها صاف و چسبیده بمانند و به سمت سقف بلند شوند.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0865":{"name":"بلندکردن پا-ران خوابیده","steps":["به پشت دراز بکشید؛ پاها صاف و بازوها کنار بدن.","برای تکیه، دست‌ها را زیر باسن بگذارید.","میان‌تنه را منقبض کنید و پاها را از زمین بلند کنید؛ به سمت سقف.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1301":{"name":"پرس سینه داخلی دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و با کمر صاف چسبیده به پد روی دستگاه جای بگیرید.","دسته‌ها را با دست از پشت بگیرید و آرنج‌ها را با زاویه ۹۰ درجه قرار دهید.","دسته‌ها را تا صاف‌شدن کامل بازوها به جلو پرس کنید و در طول حرکت بازدم کنید.","در انتهای حرکت مکث کنید، سپس با دم به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0624":{"name":"درازنشست رژه (روی دیوار)","steps":["با کمر چسبیده به دیوار و پاهای به عرض لگن بایستید.","کمر را به‌آرامی روی دیوار پایین سر بخورید تا زانوها ۹۰ درجه خم شوند.","پای راست را از زمین بلند کنید و زانو را به سمت سینه بیاورید.","پای راست را پایین برگردانید و پای چپ را از زمین بلند کنید؛ زانو به سمت سینه.","برای تعداد دلخواه تکرار، بلندکردن پای راست و چپ را یک‌درمیان ادامه دهید."]},
"1353":{"name":"پرتاب توپ پزشکی از بالای سر","steps":["با پاهای به عرض شانه بایستید و توپ پزشکی را با هر دو دست هم‌سطح سینه بگیرید.","زانوها را کمی خم کنید و عضلات میان‌تنه را منقبض کنید.","بدن را به حالت اسکوات پایین ببرید؛ کمر صاف و سینه بالا.","لگن و پاها را با قدرت صاف کنید و همزمان توپ پزشکی را از بالای سر پرتاب کنید.","توپ را در اوج حرکت رها کنید و هنگام پایین‌آمدن بگیرید.","بدن را به حالت اسکوات برگردانید و برای تعداد دلخواه تکرار کنید."]},
"1302":{"name":"پاس سینه توپ پزشکی","steps":["بایستید، پاها به عرض شانه و توپ پزشکی را هم‌سطح سینه نگه دارید.","بازوها را به جلو دراز کنید و توپ پزشکی را با قدرت از سینه دور کنید.","همزمان با رهاسازی توپ، حرکت را با بازوها و تنه ادامه دهید و وزن را از پای عقب به پای جلو منتقل کنید.","وقتی توپ از دیوار یا شریک تمرینی برگشت، آن را بگیرید و فوراً حرکت را تکرار کنید.","برای تعداد دلخواه تکرار ادامه دهید."]},
"1303":{"name":"پرس سینه توپ پزشکی از حالت سه‌نقطه","steps":["در حالت سه‌نقطه شروع کنید؛ یک دست روی توپ پزشکی و دست دیگر روی زمین.","پاها را دراز کنید و بدن را در خطی صاف قرار دهید.","سینه را با کمر صاف به سمت زمین پایین ببرید.","توپ پزشکی را با دراز‌کردن کامل بازو از بدن دور کنید.","به موقعیت شروع برگردید و برای تعداد دلخواه تکرار کنید."]},
"1304":{"name":"پرس سینه توپ پزشکی چندپاسخ","steps":["بایستید، پاها به عرض شانه و توپ پزشکی را هم‌سطح سینه نگه دارید.","بازوها را به جلو دراز کنید و توپ پزشکی را از سینه خود دور کنید.","لحظه‌ای مکث کنید، سپس توپ پزشکی را به‌آرامی به سینه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1305":{"name":"پرس سینه توپ پزشکی تک‌پاسخ","steps":["بایستید، پاها به عرض شانه و توپ پزشکی را هم‌سطح سینه نگه دارید.","بازوها را به جلو دراز کنید و توپ پزشکی را از سینه خود دور کنید.","لحظه‌ای مکث کنید، سپس توپ پزشکی را به‌آرامی به سینه برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1312":{"name":"پرس سینه توپ پزشکی با رهاسازی در دویدن","steps":["بایستید، پاها به عرض شانه و توپ پزشکی را هم‌سطح سینه نگه دارید.","با پای راست به جلو گام بردارید و همزمان توپ پزشکی را با بازوهای کاملاً صاف به جلو پرس کنید.","همزمان با هُل دادن توپ به جلو، آن را رها کنید تا به جلو بخزد.","سریع به جلو بدوید و قبل از برخورد توپ با زمین آن را بگیرید.","وقتی توپ را گرفتید، آن را به سینه برگردانید و حرکت را با پای چپ جلو تکرار کنید.","پاها را یک‌درمیان عوض کنید و حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"1701":{"name":"شنا سوئدی دست جمع با توپ پزشکی","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها روی توپ پزشکی به عرض شانه.","با خم‌کردن آرنج‌ها و نگه‌داشتن آن‌ها نزدیک بدن، بدن را به سمت زمین پایین ببرید.","با بازوهای کاملاً صاف به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1354":{"name":"ضربه از بالای سر با توپ پزشکی","steps":["با پاهای به عرض شانه بایستید و توپ پزشکی را با هر دو دست بالای سر بگیرید.","میان‌تنه را منقبض و کمر را صاف نگه دارید.","زانوها را کمی خم کنید و توپ پزشکی را با قدرت روی زمین جلوی خود بکوبید.","همزمان با کوبیدن توپ به زمین، برای ایجاد قدرت از کل بدن شامل سرشانه و میان‌تنه استفاده کنید.","توپ را هنگام برگشت از زمین بگیرید و برای تعداد دلخواه تکرار کنید."]},
"1750":{"name":"پرتاب سینه به پشت خوابیده با توپ پزشکی","steps":["به پشت روی میز دراز بکشید؛ زانوها خم و کف پاها صاف روی زمین.","توپ پزشکی را با هر دو دست بگیرید و بازوها را صاف بالای سینه دراز کنید.","توپ پزشکی را با آرنج‌های نزدیک بدن به سمت سینه پایین ببرید.","توپ پزشکی را با قدرت به بالا پرس کنید؛ بازوها کاملاً صاف و توپ تا حداکثر ارتفاع پرتاب شود.","توپ پزشکی را بگیرید و برای تعداد دلخواه تکرار کنید."]},
"0627":{"name":"بارفیکس دست جمع با گریپ ترکیبی","steps":["میله بارفیکس را با دست از جلو (کف رو به خودتان) و کمی بازتر از عرض شانه بگیرید.","از هالتر آویزان شوید؛ بازوها کاملاً صاف و پاها از زمین جدا.","عضلات پشت را منقبض کنید و با پیشتازی سینه، بدن را به سمت هالتر بکشید.","کشش را ادامه دهید تا چانه از هالتر بالاتر برود.","در بالای حرکت مکث کنید، سپس با کنترل بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3217":{"name":"شنا سوئدی هندو اصلاح‌شده (مرد)","steps":["در حالت شنا سوئدی با دست‌های کمی بازتر از عرض شانه و پاهای به عرض لگن شروع کنید.","بدن را با خم‌کردن آرنج‌ها و میان‌تنه منقبض به سمت زمین پایین ببرید.","همزمان با پایین‌بردن بدن، وزن را به عقب منتقل کنید و لگن را به سمت سقف بلند کنید تا بدن حالت V وارونه بگیرد.","پایین‌رفتن را ادامه دهید تا سینه کمی بالای زمین برسد، سپس جهت را عوض کنید؛ لگن را پایین بدهید و با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1421":{"name":"شنا سوئدی با ساعد اصلاح‌شده","steps":["در حالت شنا سوئدی با دست‌های دقیقاً زیر شانه و بدن در خطی صاف شروع کنید.","بدن را با خم‌کردن آرنج‌های نزدیک پهلوها به سمت زمین پایین ببرید.","وقتی آرنج‌ها ۹۰ درجه شدند، ساعدها را به زمین بگذارید؛ آرنج‌ها دقیقاً زیر شانه‌ها.","لحظه‌ای مکث کنید، سپس با فشار کف دست‌ها ساعدها را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0628":{"name":"قدم هیولایی (مونستر واک)","steps":["کش مقاومتی را دور مچ پاها قرار دهید.","با پاهای به عرض شانه و کمی خم در زانوها بایستید.","با پای راست به پهلو قدم بردارید و کشش کش حفظ شود.","پای چپ را هم به پهلو ببرید تا به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کنید."]},
"0630":{"name":"کوهنورد","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها دقیقاً زیر شانه‌ها و بدن در یک خط صاف.","میان‌تنه را منقبض کنید و زانوی راست را به سینه بیاورید، سپس سریع عوض کنید و زانوی چپ را به سینه ببرید.","پاها را در حالت دویدن یک‌درمیان عوض کنید؛ لگن پایین و میان‌تنه منقبض.","در طول حرکت سرعت ثابت و تنفس یکنواخت داشته باشید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0631":{"name":"ماسل‌آپ","steps":["از میله بارفیکس آویزان شوید؛ کف دست‌ها رو به بیرون و بازوها کاملاً صاف.","میان‌تنه را منقبض کنید و با پیشتازی سینه، بدن را به سمت هالتر بکشید.","در اوج حرکت، گریپ را عوض کنید تا کف دست‌ها رو به خودتان شود.","بالاکشیدن را ادامه دهید تا سینه از هالتر بالاتر برود و بازوها کاملاً جمع شوند.","حرکت را با پایین‌آوردن به‌آرامی خود به موقعیت شروع برعکس کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1401":{"name":"ماسل‌آپ (روی هالتر عمودی)","steps":["از میله عمودی با کف دست‌ها رو به بیرون و بازوهای کاملاً صاف آویزان شوید.","میان‌تنه را منقبض کنید و با پیشتازی سینه، بدن را به سمت هالتر بکشید.","همزمان با بالاکشیدن بدن، کمی به عقب خم شوید و آرنج‌ها را به سمت پهلوها بیاورید.","کشیدن را ادامه دهید تا سینه به هالتر برسد و آرنج‌ها کاملاً خم شوند.","در بالای حرکت مکث کنید، سپس به‌آرامی خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2328":{"name":"شنا سوئدی دست جمع روی توپ سوئیسی","steps":["توپ سوئیسی را روی زمین بگذارید و در حالت شنا سوئدی جای بگیرید؛ دست‌ها روی توپ و کمی باریک‌تر از عرض شانه.","میان‌تنه را منقبض کنید و بدن را در خطی صاف از سر تا پنجه نگه دارید.","سینه را با خم‌کردن آرنج‌های نزدیک بدن به سمت توپ پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1403":{"name":"کشش گردن از پهلو","steps":["ایستاده یا نشسته صاف شوید و شانه‌ها را رها کنید.","سر را به یک طرف خم کنید و گوش را به سمت شانه بیاورید.","کشش را ۱۵ تا ۳۰ ثانیه نگه دارید.","حرکت را در طرف دیگر تکرار کنید.","در هر طرف ۲ تا ۴ ست انجام دهید."]},
"0634":{"name":"کرانچ منفی","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را به‌آرامی از زمین بلند کنید و تا زاویه ۴۵ درجه به جلو خم شوید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1495":{"name":"کرانچ پهلو نسخه ۲","steps":["به پشت دراز بکشید؛ زانوها خم و کف پاها صاف روی زمین.","دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.","شکم را منقبض کنید و کتف‌ها را از زمین بلند کنید؛ تنه را به یک طرف بچرخانید.","لحظه‌ای مکث کنید، سپس کتف‌ها را به موقعیت شروع برگردانید.","حرکت را در طرف دیگر تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0635":{"name":"کرانچ پهلو روی زمین","steps":["به پشت دراز بکشید؛ زانوها خم و کف پاها صاف روی زمین.","دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.","شکم را منقبض کنید و کتف‌ها را از زمین بلند کنید؛ تنه را به یک طرف بچرخانید.","لحظه‌ای مکث کنید، سپس کتف‌ها را به زمین برگردانید.","در طرف دیگر با تعویض طرف در هر تکرار ادامه دهید."]},
"0636":{"name":"جلوبازو چکشی هالتر المپیک","steps":["صاف با پاهای به عرض شانه بایستید و هالتر المپیک را با دست از پشت بگیرید.","اجازه دهید هالتر با فاصله یک بازو جلوی ران‌ها و کف دست‌ها رو به بدن آویزان باشد.","بازوها را ثابت نگه دارید، بازدم کنید و با انقباض جلوبازو وزنه‌ها را بالا بکشید.","هالتر را تا انقباض کامل جلوبازو و هم‌سطح شانه بالا ببرید.","در حالت انقباضی کمی مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و به‌آرامی هالتر را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0637":{"name":"پشت‌بازو هالتر المپیک","steps":["ایستاده شروع کنید؛ پاها به عرض شانه و هالتر با دست از پشت.","هالتر را با بازوهای کاملاً صاف بالای سر ببرید.","بازوها را نزدیک سر نگه دارید و با خم‌کردن آرنج‌ها، هالتر را به‌آرامی پشت سر پایین ببرید.","لحظه‌ای مکث کنید، سپس بازوها را به موقعیت شروع صاف کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1355":{"name":"زیربغل تک‌دست با تکیه به دیوار","steps":["روبه‌روی دیوار با پاهای به عرض شانه بایستید.","یک بازو را صاف جلوی خود دراز کنید و کف دست را به دیوار تکیه دهید.","میان‌تنه را منقبض کنید و بدن را به جلو خم کنید؛ بازو صاف و کمر صاف.","کف دست را به‌آرامی به دیوار فشار دهید و زیربغل را فعال کنید.","حالت را چند ثانیه نگه دارید، سپس رها کنید و با دست دیگر تکرار کنید."]},
"0638":{"name":"بارفیکس تک‌دست","steps":["روبه‌روی میله بارفیکس با پاهای به عرض شانه بایستید.","بالا بروید و هالتر را با دست از جلو بگیرید؛ یک دست هالتر و دیگری برای تکیه مچ را بگیرد.","با بازوی کاملاً صاف از هالتر آویزان شوید؛ بدن صاف و میان‌تنه منقبض.","خود را با خم‌کردن آرنج و انقباض عضلات پشت به سمت هالتر بکشید.","کشش را ادامه دهید تا چانه از هالتر بالاتر برود، سپس به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کرده و دوباره تکرار کنید."]},
"0639":{"name":"پارالل تک‌دست","steps":["پشت به میز یا صندلی با پاهای به عرض شانه بایستید.","یک دست را پشت سر روی میز یا صندلی بگذارید؛ انگشتان رو به بدن.","پاها را جلوی خود دراز کنید؛ پاشنه‌ها روی زمین.","آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید؛ کمر نزدیک میز یا صندلی.","در پایین‌ترین نقطه مکث کنید، سپس با فشار کف دست‌ها بازوها را صاف و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار کنید، سپس طرف را عوض کرده و با دست دیگر تکرار کنید."]},
"0640":{"name":"ضربه تک‌دست (با توپ پزشکی)","steps":["با پاهای به عرض شانه بایستید و توپ پزشکی را با یک دست جلوی کمر بگیرید.","زانوها را کمی خم کنید و عضلات میان‌تنه را منقبض کنید.","توپ پزشکی را با بازوی کاملاً صاف بالای سر ببرید.","توپ پزشکی را با قدرت روی زمین بکوبید؛ برای ایجاد قدرت از میان‌تنه و سرشانه استفاده کنید.","توپ پزشکی را هنگام برگشت از زمین بگیرید و برای تعداد دلخواه تکرار کنید."]},
"1773":{"name":"زیربغل تک‌دست با حوله","steps":["بایستید، پاها به عرض شانه، زانوها کمی خم و حوله را در یک دست بگیرید.","از کمر به جلو خم شوید و کمر را صاف و میان‌تنه را منقبض نگه دارید.","بازو را کاملاً دراز کنید و اجازه دهید حوله جلوی شما آویزان باشد.","حوله را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت مکث کنید، سپس حوله را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس دست را عوض کنید."]},
"1386":{"name":"ساق پا دونکی تک‌پا","steps":["بایستید، پاها به عرض شانه و پنجه‌ها رو به جلو.","برای تکیه، دست‌ها را روی سطح ثابتی مثل دیوار یا میله بگذارید.","یک پا را با کمی خم در زانو از زمین بلند کنید.","با عضلات ساق، پاشنه را تا حد ممکن بالا ببرید.","در بالای حرکت مکث کنید، سپس پاشنه را به‌آرامی پایین ببرید.","برای تعداد دلخواه تکرار کنید، سپس پا را عوض کنید."]},
"1387":{"name":"ساق پا زمین تک‌پا","steps":["با پاهای به عرض لگن بایستید و برای تعادل دست‌ها را روی دیوار یا جسم محکم بگذارید.","یک پا را از زمین بلند کنید و روی پای دیگر تعادل بگیرید.","پاشنه را به‌آرامی از زمین بلند کنید و بدن را روی پنجه پا بالا ببرید.","در بالای حرکت مکث کنید، سپس پاشنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس پاها را عوض کنید و دوباره تکرار کنید."]},
"1476":{"name":"اسکوات تک‌پا","steps":["بایستید و پاها را به عرض شانه باز کنید.","یک پا را به جلو دراز کنید و از زمین جدا نگه دارید.","پای ایستاده را خم کنید و مثل نشستن روی صندلی بدن را پایین ببرید.","سینه را بالا و کمر را صاف نگه دارید.","با فشار پاشنه به موقعیت شروع برگردید.","حرکت را با پای دیگر تکرار کنید."]},
"0641":{"name":"اُتیس‌آپ (بلندکردن وزنه خوابیده)","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را به‌آرامی از زمین بلند کنید و تا زاویه ۴۵ درجه به جلو خم شوید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0642":{"name":"شنا سوئدی با ضربه پا بیرونی","steps":["در حالت شنا سوئدی شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و پاها چسبیده.","با خم‌کردن آرنج‌ها و کمر صاف و میان‌تنه منقبض، بدن را به سمت زمین پایین ببرید.","همزمان با برگشتن به بالا، یک پا را کاملاً صاف به پهلو پرت کنید و باسن را منقبض کنید.","پا را به موقعیت شروع برگردانید و شنا را تکرار کنید؛ پاها در هر تکرار عوض شوند.","ضربات پا و شنا سوئدی را یک‌درمیان برای تعداد دلخواه تکرار ادامه دهید."]},
"0643":{"name":"کشش پشت‌بازو از بالا","steps":["ایستاده یا نشسته با پاهای به عرض شانه باشید.","یک بازو را بالای سر دراز کنید و آرنج را خم کنید تا دست به سمت کتف مخالف برسد.","با دست دیگر، آرنج بازوی درازشده را به‌آرامی به سمت طرف مخالف سر بکشید تا کشش پشت‌بازو را احساس کنید.","کشش را ۱۵ تا ۳۰ ثانیه نگه دارید، سپس رها کنید.","حرکت را در طرف دیگر تکرار کنید."]},
"3147":{"name":"انحراف لگن","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را کنار بدن قرار دهید.","شکم را منقبض کنید و لگن را به بالا بچرخانید؛ کمر را به زمین بفشارید.","این حالت را چند ثانیه نگه دارید و روی انقباض شکم تمرکز کنید.","خم‌شدگی را رها کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1422":{"name":"انحراف لگن تا پل باسن","steps":["به پشت دراز بکشید؛ زانوها خم و کف پاها صاف روی زمین.","بازوها را کنار بدن و کف دست‌ها رو به پایین قرار دهید.","عضلات باسن و میان‌تنه را منقبض کنید.","لگن را به بالا بچرخانید و لگن را از زمین بلند کنید.","حالت پل را چند ثانیه نگه دارید.","لگن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1388":{"name":"کشش نازک‌نژی (پرونئال) با طناب","steps":["روی زمین بنشینید و پاها را در مقابل خود صاف کنید.","طناب را دور پنجه پا بپیچید و دو سر آن را با دست‌ها بگیرید.","طناب را به‌آرامی به سمت خود بکشید، پا را به سمت بالا خم کنید و عضلات ساق را بکشید.","کشش را ۱۵ تا ۳۰ ثانیه نگه دارید.","کشش طناب را رها کنید و کشش را با پای دیگر تکرار کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3662":{"name":"شنا سوئدی پایک تا کبرا","steps":["در حالت شنا سوئدی شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و پاها چسبیده.","میان‌تنه را منقبض کنید و لگن را به سمت سقف بلند کنید تا بدن حالت V وارونه بگیرد.","تنه بالایی را با خم‌کردن آرنج‌های نزدیک بدن به سمت زمین پایین ببرید.","همزمان با پایین‌رفتن، وزن را به جلو منتقل کنید و با صاف‌کردن بازوها و بلندکردن سینه به حالت کبرا بروید.","حرکت را با خم‌کردن آرنج‌ها و پایین‌بردن سینه به سمت زمین برعکس کنید.","با فشار دست‌ها به حالت V وارونه برگردید.","حرکت را با پایین‌آوردن لگن به سمت زمین ادامه دهید و به حالت شروع شنا سوئدی برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1306":{"name":"شنا سوئدی پلایومتریک","steps":["در حالت پلانک بلند شروع کنید و دست‌ها را کمی بازتر از عرض شانه بگذارید.","سینه را با خم‌کردن آرنج‌ها و بدن صاف به سمت زمین پایین ببرید.","با استفاده از عضلات سینه و فشار انفجاری، تنه بالایی را از زمین جدا کنید.","با دست‌ها نرم به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1687":{"name":"گام از عقب با کشش از بالا","steps":["با پاهای به عرض لگن و بازوهای کنار بدن بایستید.","با پای راست به عقب قدم بردارید و روی پنجه فرود بیایید.","زانوی چپ را خم کنید و بدن را به حالت لانژ پایین ببرید.","همزمان با پایین‌رفتن به حالت لانژ، بازوها را بالای سر دراز کنید.","در پایین‌ترین نقطه لانژ مکث کنید، سپس با فشار پاشنه چپ و آوردن پای راست به جلو به موقعیت شروع برگردید.","حرکت را در طرف دیگر با گام پای چپ به عقب و خم‌کردن زانوی راست تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"1389":{"name":"کشش تیبیالیس خلفی با طناب","steps":["روی زمین بنشینید و پاها را در مقابل خود صاف کنید.","طناب را دور پنجه پا بپیچید و دو سر آن را با دست‌ها بگیرید.","طناب را به‌آرامی به سمت خود بکشید، پا را به سمت بالا خم کنید و عضلات ساق را بکشید.","کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.","کشش طناب را رها کنید و پا را رها کنید.","کشش را با پای دیگر تکرار کنید."]},
"3119":{"name":"اسکوات توالت‌نشین","steps":["بایستید، پاها به عرض شانه و پنجه‌ها کمی رو به بیرون.","بدن را با خم‌کردن زانوها و عقب‌بردن لگن پایین ببرید؛ مثل نشستن روی صندلی.","در طول حرکت سینه را بالا و کمر را صاف نگه دارید.","پایین بروید تا ران‌ها موازی زمین شوند یا تا حداکثر عمق راحت.","در پایین‌ترین نقطه مکث کنید، سپس با فشار پاشنه‌ها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3132":{"name":"اسکوات توالت‌نشین با تکیه‌گاه","steps":["بایستید، پاها به عرض شانه و پنجه‌ها کمی رو به بیرون.","برای تعادل به تکیه‌گاه ثابتی مثل صندلی یا دیوار بگیرید.","با خم‌کردن زانوها و عقب‌بردن لگن، بدن را به حالت اسکوات پایین ببرید.","در طول حرکت سینه را بالا و کمر را صاف نگه دارید.","در پایین‌ترین نقطه مکث کنید، سپس با فشار پاشنه‌ها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0648":{"name":"کلین قدرتی هالتر","steps":["با هالتر روی زمین جلوی شما و پاهای به عرض شانه شروع کنید.","خم شوید و هالتر را با دست از پشت و کمی بازتر از عرض شانه بگیرید.","هنگام بلندکردن هالتر از زمین با صاف‌کردن لگن و زانوها، کمر صاف و سینه بالا باشد.","وقتی هالتر به میانه ران رسید، با قدرت آن را بالا بکشید؛ شانه‌ها را بالا بیندازید و آرنج‌ها را بالا و به طرفین بکشید.","وقتی هالتر به بالاترین نقطه رسید، سریع زیر آن بروید؛ آرنج‌ها را بچرخانید و هالتر را در حالت اسکوات از جلو روی شانه‌ها بگیرید.","با هالتر بلند شوید؛ لگن و زانوها کاملاً صاف.","هالتر را با کنترل کامل وزنه در طول حرکت به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3665":{"name":"پلانک نقطه قدرت","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها دقیقاً زیر شانه و بدن در خطی صاف از سر تا پنجه.","میان‌تنه و باسن را منقبض کنید تا حالت پایدار حفظ شود.","بدن را یکی‌یکی روی ساعدها پایین ببرید؛ خط صاف از سر تا پنجه حفظ شود.","این حالت را برای مدت دلخواه نگه دارید؛ میان‌تنه و باسن منقبض.","برای برگشتن به موقعیت شروع، با فشار ساعدها بدن را به حالت پلانک بلند برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3203":{"name":"درازنشست نیمه زندانی (مرد)","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را به‌آرامی از زمین بلند کنید و تا زاویه ۴۵ درجه به جلو خم شوید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1707":{"name":"چرخش رو به زمین روی توپ سوئیسی","steps":["رو به زمین روی توپ سوئیسی دراز بکشید؛ پاها به عرض شانه و پنجه‌ها در تماس با زمین.","دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.","عضلات میان‌تنه را منقبض کنید و تنه را به‌آرامی از روی توپ بلند کنید؛ کمر صاف.","تنه را به یک طرف بچرخانید و شانه را به سمت لگن بیاورید؛ لگن و پاها در طول حرکت پایدار بمانند.","لحظه‌ای مکث کنید، سپس به موقعیت شروع برگردید.","چرخش را به طرف دیگر تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"0651":{"name":"بارفیکس با دست خنثی","steps":["از میله بارفیکس با گریپ خنثی (کف دست‌ها رو به هم) و بازوهای کاملاً صاف آویزان شوید.","میان‌تنه را منقبض کنید و کتف‌ها را به هم فشار دهید.","بدن را با خم‌کردن آرنج‌ها و هُل دادن آنها به سمت لگن بالا بکشید.","کشش را ادامه دهید تا چانه از هالتر بالاتر برود.","در بالای حرکت مکث کنید، سپس با کنترل بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0650":{"name":"کشیدن پا روی توپ سوئیسی","steps":["روی توپ سوئیسی بنشینید؛ کف پاها صاف روی زمین و زانوها با زاویه ۹۰ درجه خم.","دست‌ها را برای تکیه روی کناره‌های توپ سوئیسی بگذارید.","شکم را منقبض کنید و لگن را به‌آرامی به جلو بغلتانید؛ زانوها به سمت سینه.","در بالای حرکت مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع دراز کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0652":{"name":"بارفیکس","steps":["از میله بارفیکس با کف دست‌ها رو به بیرون و بازوهای کاملاً صاف آویزان شوید.","میان‌تنه را منقبض کنید و کتف‌ها را به هم فشار دهید.","بدن را با خم‌کردن آرنج‌ها و آوردن سینه به سمت هالتر بالا بکشید.","در بالای حرکت مکث کنید، سپس بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1689":{"name":"پیشران و کشش با وزن بدن","steps":["در حالت شنا سوئدی با دست‌های کمی بازتر از عرض شانه و بدن در خطی صاف شروع کنید.","با خم‌کردن آرنج‌ها و بدن صاف، سینه را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","از حالت شنا سوئدی، با خم‌کردن آرنج‌ها و بدن صاف سینه را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3638":{"name":"پرس تا دویدن","steps":["در حالت شنا سوئدی شروع کنید؛ دست‌ها به عرض شانه و بدن در خطی صاف.","با خم‌کردن آرنج‌ها و بدن صاف، سینه را به سمت زمین پایین ببرید.","با فشار دست‌ها بازوها را دراز و به موقعیت شروع برگردید.","سریع یک زانو را به سینه بیاورید، سپس سریع عوض کنید و زانوی دیگر را به سینه ببرید.","زانوها را با حفظ فرم درست، تا جایی که می‌توانید سریع یک‌درمیان بالا ببرید.","برای مدت یا تعداد تکرار دلخواه ادامه دهید."]},
"1307":{"name":"شنا سوئدی روی بوسو","steps":["نیم‌توپ بوسو را با سمت صاف رو به بالا روی زمین بگذارید.","در حالت شنا سوئدی جای بگیرید و دست‌ها را روی لبه‌های بیرونی بوسو بگذارید.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌ها بدن را به سمت بوسو پایین ببرید.","با صاف‌کردن بازوها خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0662":{"name":"شنا سوئدی","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و پاها چسبیده.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌ها و بدن صاف، بدن را به سمت زمین پایین ببرید.","وقتی سینه کمی بالای زمین بود مکث کنید، سپس با صاف‌کردن بازوها خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0653":{"name":"شنا سوئدی (روی بوسو)","steps":["نیم‌توپ بوسو را با سمت صاف رو به بالا روی زمین بگذارید.","در حالت شنا سوئدی جای بگیرید و دست‌ها را روی لبه‌های بیرونی بوسو بگذارید.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌ها بدن را به سمت بوسو پایین ببرید.","با صاف‌کردن بازوها خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0655":{"name":"شنا سوئدی (روی توپ سوئیسی)","steps":["توپ سوئیسی را روی زمین بگذارید و رو به پایین جای بگیرید؛ دست‌ها روی توپ به عرض شانه.","پاها را صاف پشت سر دراز کنید و روی پنجه‌ها تعادل بگیرید.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌ها و خط صاف بدن، سینه را به سمت توپ پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0656":{"name":"شنا سوئدی (روی توپ سوئیسی)","steps":["توپ سوئیسی را روی زمین بگذارید و رو به پایین جای بگیرید؛ دست‌ها روی توپ به عرض شانه.","پاها را صاف پشت سر دراز کنید و روی پنجه‌ها تعادل بگیرید.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌ها و خط صاف بدن، سینه را به سمت توپ پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0659":{"name":"شنا سوئدی (دیواری)","steps":["در فاصله یک بازو از دیوار بایستید.","دست‌ها را در ارتفاع شانه و کمی بازتر از عرض شانه روی دیوار بگذارید.","چند قدم به عقب بروید؛ بدن صاف و پاها به عرض لگن.","آرنج‌ها را خم کنید و سینه را به سمت دیوار پایین ببرید؛ بدن در خطی صاف.","با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0658":{"name":"شنا سوئدی (دیواری) نسخه ۲","steps":["در فاصله یک بازو از دیوار بایستید.","دست‌ها را در ارتفاع شانه و کمی بازتر از عرض شانه روی دیوار بگذارید.","با هر دو پا و به عرض لگن به عقب بروید.","میان‌تنه را منقبض کنید و بدن را در خطی صاف از سر تا پاشنه نگه دارید.","آرنج‌ها را خم کنید و سینه را به سمت دیوار پایین ببرید؛ بدن صاف.","لحظه‌ای مکث کنید، سپس خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0660":{"name":"شنا سوئدی دست جمع روی دمبل","steps":["در حالت شنا سوئدی با دست‌های نزدیک هم و دقیقاً زیر شانه‌ها شروع کنید.","در هر دست دمبل بگیرید و روی زمین بگذارید.","با خم‌کردن آرنج‌ها و نگه‌داشتن آن‌ها نزدیک بدن، بدن را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0661":{"name":"شنا سوئدی با ضربه پا داخلی","steps":["در حالت شنا سوئدی شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و پاها چسبیده.","بدن را با خم‌کردن آرنج‌ها، کمر صاف و میان‌تنه منقبض به سمت زمین پایین ببرید.","همزمان با برگشتن به بالا، یک پا را از زمین بلند کنید و صاف به پهلو پرت کنید.","پا را پایین برگردانید، شنا را تکرار کنید و سپس پای دیگر را عوض کنید.","در هر تکرار شنا سوئدی، ضربه پا را یک‌درمیان عوض کنید."]},
"0663":{"name":"شنا سوئدی با توپ پزشکی","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها روی توپ پزشکی به عرض شانه.","میان‌تنه را منقبض کنید و با خم‌کردن آرنج‌ها و کمر صاف، بدن را به سمت زمین پایین ببرید.","با فشار کف دست‌ها بازوها را صاف کنید و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1467":{"name":"شنا سوئدی روی ساعدها","steps":["در حالت پلانک با ساعدها روی زمین و آرنج‌های دقیقاً زیر شانه‌ها شروع کنید.","میان‌تنه را منقبض کنید و بدن را در خطی صاف از سر تا پنجه نگه دارید.","با خم‌کردن آرنج‌ها و نزدیک‌نگه‌داشتن آن‌ها به بدن، سینه را به سمت زمین پایین ببرید.","در پایین‌ترین نقطه مکث کنید، سپس بدن را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3145":{"name":"شنا سوئدی پلاس","steps":["در حالت پلانک بلند شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و بدن در خطی صاف از سر تا پاشنه.","با خم‌کردن آرنج‌ها و نگه‌داشتن آن‌ها نزدیک بدن، بدن را به سمت زمین پایین ببرید.","وقتی سینه کمی بالای زمین بود، با فشار دست‌ها بازوها را صاف کنید و تنه بالایی را بلند کنید.","در بالای حرکت، با هُل دادن پشت بالایی به سمت سقف کتف‌ها را از هم باز کنید.","لحظه‌ای مکث کنید، سپس با جمع‌کردن کتف‌ها حرکت را برعکس و بدن را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0664":{"name":"شنا سوئدی تا پلانک از پهلو","steps":["در حالت شنا سوئدی شروع کنید؛ دست‌ها به عرض شانه و بدن در خطی صاف.","با خم‌کردن آرنج‌ها و میان‌تنه منقبض، بدن را به سمت زمین پایین ببرید.","به موقعیت شروع برگردید.","وزن را روی دست چپ بیندازید و بدن را به راست بچرخانید؛ دست راست به سمت سقف.","حالت پلانک از پهلو را چند ثانیه نگه دارید، سپس به موقعیت شروع برگردید.","شنا سوئدی و پلانک از پهلو را در طرف مخالف تکرار کنید.","به‌تناوب از طرفین حرکت را برای تعداد دلخواه تکرار ادامه دهید."]},
"3533":{"name":"چارسر ران با وزن بدن","steps":["بایستید و پاها را به عرض شانه باز کنید.","بدن را با خم‌کردن زانوها و عقب‌بردن لگن پایین ببرید؛ مثل نشستن روی صندلی.","سینه را بالا و کمر را صاف نگه دارید.","پایین بروید تا ران‌ها موازی زمین شوند.","با فشار پاشنه‌ها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3201":{"name":"درازنشست یک‌چهارم","steps":["به پشت دراز بکشید، زانوها را خم کنید و کف پاها را صاف روی زمین بگذارید.","دست‌ها را پشت سر بگذارید و آرنج‌ها را رو به بیرون نگه دارید.","با انقباض شکم، تنه را به‌آرامی از زمین بلند کنید و تا زاویه ۴۵ درجه به جلو خم شوید.","در بالای حرکت لحظه‌ای مکث کنید، سپس تنه را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3552":{"name":"قدم‌های سریع نسخه ۲","steps":["بایستید، پاها به عرض شانه و بازوها کنار بدن.","با بالا و پایین‌بردن سریع پاها شروع کنید؛ مثل دویدن درجا.","حرکات سریع و سبک باشد و روی ماندن روی پنجه‌ها تمرکز کنید.","برای مدت یا تعداد تکرار دلخواه ادامه دهید."]},
"0666":{"name":"شنا سوئدی تک‌دست با بلندکردن بازو","steps":["در حالت شنا سوئدی شروع کنید؛ دست‌ها کمی بازتر از عرض شانه و پاها چسبیده.","یک بازو را صاف به پهلو و موازی زمین دراز کنید.","با خم‌کردن آرنج‌ها و کمر صاف و میان‌تنه منقبض، بدن را به سمت زمین پایین ببرید.","با استفاده از عضلات سینه و بلندکردن بدن، به موقعیت شروع برگردید.","با دراز‌کردن دست دیگر تکرار کنید."]},
"0668":{"name":"پل باسن از عقب","steps":["به پشت دراز بکشید؛ کف پاها صاف روی زمین و زانوها خم.","بازوها را کنار بدن و کف دست‌ها رو به پایین قرار دهید.","باسن و پشت پا را منقبض کنید و لگن را از زمین بلند کنید تا بدن از زانو تا شانه خطی صاف بسازد.","این حالت را چند ثانیه نگه دارید، سپس لگن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0669":{"name":"کشش دلتوئید خلفی","steps":["صاف بایستید و پاها را به عرض شانه باز کنید.","بازوی راست را ضربدری روی سینه دراز کنید و دست چپ را روی آرنج راست بگذارید.","بازوی راست را به‌آرامی به سمت شانه چپ بکشید تا کشش سرشانه راست را احساس کنید.","کشش را ۱۵ تا ۳۰ ثانیه نگه دارید، سپس رها کنید.","حرکت را در طرف دیگر تکرار کنید."]},
"0670":{"name":"بارفیکس از عقب","steps":["میله بارفیکس را با دست از پشت، کمی بازتر از عرض شانه بگیرید.","از هالتر آویزان شوید؛ بازوها کاملاً صاف و بدن صاف باشد.","عضلات پشت را منقبض کنید و با آرنج‌های نزدیک بدن، بدن را به سمت هالتر بکشید.","کشش را ادامه دهید تا چانه از هالتر بالاتر برود.","در بالای حرکت لحظه‌ای مکث کنید، سپس بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1582":{"name":"کشش انگشت بزرگ پا خوابیده با طناب","steps":["به پشت دراز بکشید؛ پاها دراز و بازوها کنار بدن.","طناب را دور پنجه پای راست بپیچید و دو سر آن را با دست‌ها بگیرید.","پای راست را با زانوی صاف و پنجه خم به‌آرامی به سمت سینه بالا ببرید.","کشش را چند ثانیه نگه دارید، سپس پا را به‌آرامی به موقعیت شروع برگردانید.","حرکت را با پای چپ تکرار کنید.","به‌تناوب پاها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"3236":{"name":"هیپ تراست زانوزده با کش مقاومتی (زن)","steps":["روی زمین زانو بزنید؛ زانوها به عرض لگن و پنجه‌ها خم.","کش مقاومتی را دور ران‌ها، کمی بالای زانوها بپیچید.","دست‌ها را روی لگن بگذارید یا برای تعادل جلوی خود دراز کنید.","عضلات باسن و میان‌تنه را منقبض کنید.","همزمان با بلندکردن زانوها از زمین، لگن را به جلو هُل دهید و باسن را منقبض کنید؛ لگن تا موازی‌شدن ران‌ها با زمین صاف شود.","حالت را لحظه‌ای نگه دارید، سپس زانوها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3007":{"name":"جلو پا با کش مقاومتی","steps":["کش مقاومتی را به نقطه اتصال محکم ببندید و دور مچ پا ثابت کنید.","روبه‌روی نقطه اتصال بایستید و پاها را به عرض شانه باز کنید.","با میان‌تنه منقبض و تنه پایدار، پا را صاف جلوی خود دراز کنید.","در بالا مکث کنید، سپس پا را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار کنید، سپس پا را عوض کنید."]},
"3123":{"name":"جلوبازو نشسته با کش مقاومتی","steps":["روی صندلی یا میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","کش مقاومتی را با دست از جلو و کف رو به بالا بگیرید؛ بازوها کنار بدن دراز.","بازوها ثابت بمانند و همزمان با بازدم، کش به سمت شانه‌ها بالا کشیده شود.","در بالای حرکت مکث کنید و جلوبازو را منقبض نگه دارید.","نفس بگیرید و کش مقاومتی را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3124":{"name":"پرس سینه نشسته با کش مقاومتی","steps":["روی صندلی یا میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","دسته‌های کش مقاومتی را در هر دست بگیرید؛ کف دست‌ها رو به پایین و آرنج‌ها با زاویه ۹۰ درجه خم.","بازوها را به جلو دراز کنید و کش را از سینه دور فشار دهید.","در انتهای حرکت لحظه‌ای مکث کنید، سپس به‌آرامی به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3006":{"name":"دورکننده ران نشسته با کش مقاومتی","steps":["روی صندلی یا میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","کش مقاومتی را دور ران‌ها، کمی بالای زانوها بپیچید.","دست‌ها را برای تکیه روی کناره‌های صندلی یا میز بگذارید.","دورکننده‌های ران (عضلات بیرونی ران) را منقبض کنید و زانوها را آرام و در برابر مقاومت کش از هم باز کنید.","در انتهای حرکت مکث کنید، سپس زانوها را به‌آرامی به هم برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3122":{"name":"پرس سرشانه نشسته با کش مقاومتی","steps":["روی صندلی یا میز بنشینید، کمر صاف و کف پاها صاف روی زمین باشد.","کش مقاومتی را با هر دو دست و کف رو به جلو بگیرید و هم‌سطح شانه بالا بیاورید.","کش را با بازوهای کاملاً صاف از بالای سر پرس کنید.","در بالا مکث کنید، سپس کش را به‌آرامی تا هم‌سطح شانه پایین ببرید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3144":{"name":"زیربغل نشسته کمر صاف با کش مقاومتی","steps":["روی زمین با پاهای دراز بنشینید و کش مقاومتی را دور پاها بیندازید.","دو سر کش مقاومتی را با دست‌ها بگیرید؛ کف دست‌ها رو به هم.","کمر صاف باشد، کمی به عقب خم شوید و میان‌تنه را درگیر کنید.","کش مقاومتی را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.","در بالای حرکت مکث کنید، سپس کشش را به‌آرامی رها کرده و به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0872":{"name":"کرانچ برعکس","steps":["به پشت دراز بکشید؛ بازوها در امتداد پهلوها دراز.","زانوها را خم کنید و پاها را از زمین بلند کنید تا ران‌ها عمود بر زمین شوند.","شکم را منقبض کنید و لگن را از زمین بلند کنید؛ زانوها به سمت سینه.","در بالای حرکت لحظه‌ای مکث کنید، سپس لگن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0672":{"name":"پارالل برعکس","steps":["بین دو میله موازی جای بگیرید؛ بازوها کاملاً صاف و بدن صاف.","با خم‌کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.","لحظه‌ای مکث کنید، سپس با صاف‌کردن بازوها به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0673":{"name":"زیربغل از بالا با گریپ برعکس دستگاه","steps":["ارتفاع صندلی را تنظیم کنید و روی دستگاه جای بگیرید؛ زانوها زیر پدها و کف پاها صاف روی زمین.","دسته‌ها را با دست از جلو و کمی بازتر از عرض شانه بگیرید.","صاف بنشینید؛ سینه بیرون، شانه‌ها به عقب و قوس ملایم در کمر.","دسته‌ها را به سمت سینه پایین بکشید و کتف‌ها را به هم فشار دهید.","در پایین‌ترین نقطه حرکت مکث کنید، سپس دسته‌ها را به‌آرامی به موقعیت شروع رها کنید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0674":{"name":"بارفیکس با گریپ برعکس","steps":["میله بارفیکس را با دست از جلو و به عرض شانه بگیرید.","از هالتر آویزان شوید؛ بازوها کاملاً صاف و بدن صاف باشد.","عضلات پشت را منقبض کنید و با پیشتازی سینه، بدن را به سمت هالتر بکشید.","کشش را ادامه دهید تا چانه از هالتر بالاتر برود.","در بالای حرکت لحظه‌ای مکث کنید، سپس بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0675":{"name":"هایپرااکستنشن برعکس روی توپ سوئیسی","steps":["رو به زمین روی توپ سوئیسی دراز بکشید؛ لگن روی توپ و پاها صاف پشت سر.","دست‌ها را برای پایداری جلوی خود روی زمین بگذارید.","با انقباض باسن و پشت پا، پاها را تا حد ممکن به سمت سقف بلند کنید.","در بالای حرکت لحظه‌ای مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"1423":{"name":"هایپرااکستنشن برعکس روی میز صاف","steps":["رو به زمین روی میز صاف دراز بکشید؛ لگن در لبه میز و پاها آویزان.","برای پایداری به میز بگیرید.","با پاهای صاف، آنها را تا حد ممکن به سمت سقف بالا ببرید.","در بالای حرکت باسن را منقبض کنید.","پاها را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"3663":{"name":"پلانک برعکس با بلندکردن پا","steps":["روی زمین با پاهای دراز جلوی شما بنشینید؛ دست‌ها پشت سر روی زمین و انگشتان رو به پاها.","با فشار دست‌ها لگن را از زمین بلند کنید و به حالت پلانک معکوس بروید.","میان‌تنه را منقبض کنید و یک پا را صاف به سمت سقف از زمین بلند کنید.","لحظه‌ای مکث کنید، سپس پا را پایین برگردانید.","حرکت را با پای دیگر تکرار کنید.","به‌تناوب پاها را برای تعداد دلخواه تکرار جابه‌جا کنید."]},
"0677":{"name":"پارالل روی حلقه","steps":["از حلقه‌ها با بازوهای کاملاً صاف و بدن صاف آویزان شوید.","با خم‌کردن آرنج‌ها بدن را پایین ببرید تا شانه‌ها پایین‌تر از آرنج‌ها قرار گیرند.","با صاف‌کردن بازوها خود را به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2571":{"name":"کشش قورباغه تاب‌خورده","steps":["روی زمین با زانوهای به عرض لگن زانو بزنید.","دست‌ها را برای تکیه جلوی خود روی زمین بگذارید.","به‌آرامی به جلو خم شوید؛ وزن روی دست‌ها و پاها پشت سر دراز شود.","همزمان با عقب و بالابردن لگن به سمت سقف، کمر صاف و باسن منقبض باشد.","این حالت را چند ثانیه نگه دارید و کشش باسن را احساس کنید.","به‌آرامی با خم‌کردن زانوها و پایین‌آوردن لگن به موقعیت شروع برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"0678":{"name":"بارفیکس راکی (تاب از بالا)","steps":["جلوی میله بارفیکس با پاهای به عرض شانه بایستید.","بالا بروید و هالتر را با دست از پشت و کمی بازتر از عرض شانه بگیرید.","از هالتر آویزان شوید؛ بازوها کاملاً صاف و بدن صاف باشد.","عضلات پشت را منقبض کنید و با پیشتازی سینه، بدن را به سمت هالتر بکشید.","در بالای حرکت لحظه‌ای مکث کنید، سپس بدن را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2208":{"name":"کشش کمر با فوم رول","steps":["روی زمین بنشینید و پاها را در مقابل خود صاف کنید.","رول را عمود بر بدن، کمی زیر باسن قرار دهید.","بدن را به‌آرامی به عقب غلتانید و اجازه دهید رول روی پاها بالا برود.","غلتاندن را ادامه دهید تا رول به پشت بالایی برسد.","لحظه‌ای مکث کنید، سپس به‌آرامی به موقعیت شروع غلتیده برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2204":{"name":"ارّه‌ای بدن با فوم رول","steps":["در حالت پلانک با ساعدها روی رول و بدن در خطی صاف شروع کنید.","میان‌تنه را منقبض کنید و رول را به‌آرامی به جلو غلتانید؛ با حفظ کنترل، بدن را تا حداکثر ممکن دراز کنید.","در دورترین نقطه مکث کنید، سپس رول را به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2205":{"name":"کشش باسن و زیربغل با فوم رول","steps":["روی زمین زانو بزنید و رول زیر لگن قرار بگیرد.","دست‌ها را برای تکیه روی رول بگذارید.","رول را به‌آرامی به جلو غلتانید؛ لگن صاف و باسن کشیده شود.","کشش را چند ثانیه نگه دارید، سپس به موقعیت شروع غلتیده برگردید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2202":{"name":"کشش باسن با فوم رول","steps":["روی زمین بنشینید و پاها را در مقابل خود صاف کنید.","رول را زیر باسن، کمی بالای زانوها قرار دهید.","به عقب خم شوید و دست‌ها را برای تکیه پشت سر روی زمین بگذارید.","باسن را منقبض کنید و رول را به‌آرامی به جلو غلتانید؛ زانوها را خم و به سمت سینه بیاورید.","در انتهای حرکت مکث کنید و کشش باسن را احساس کنید.","رول را با دراز‌کردن پاها به‌آرامی به موقعیت شروع برگردانید.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]},
"2206":{"name":"کرانچ برعکس با فوم رول","steps":["به پشت دراز بکشید؛ بازوها صاف بالای سر و پاها صاف جلوی شما.","رول را بین پاها قرار دهید و با پنجه‌ها بگیرید.","با انقباض شکم، پاها را از زمین بلند و زانوها را به سینه جمع کنید؛ رول را به سمت بدن بیاورید.","در بالا مکث کنید، سپس پاها را به‌آرامی به موقعیت شروع برگردانید و رول از بدن دور شود.","برای تعداد دلخواه تکرار، حرکت را تکرار کنید."]}
});

