  if (exercise.custom) {
    image.removeAttribute('src');
    image.onerror = null;
  } else {
    image.style.display = 'block';
    fallback.style.display = 'none';
    image.src = exercise.gif_url || exercise.image;
    image.alt = `نمایش ${exercise.name}`;
    image.onerror = () => imageFallback(image);
  }

  syncMediaPill(false);

